window.REV_FLIP=window.REV_FLIP||{};window.REV_FLIP["angular"]=[{"id":"angular-f0001","card":"q-angular-001-1-course-app-prerequisites-and-project-s","sec":"angular-s002","q":"What are the prerequisites for the Angular Essential Training course?","a":"<p>TypeScript, HTML/CSS and npm. Any modern browser and OS works.</p>","hand":true},{"id":"angular-f0002","card":"q-angular-001-1-course-app-prerequisites-and-project-s","sec":"angular-s002","q":"Which dev environment does the Angular course use, and how do you start the app?","a":"<p>GitHub Codespaces (cloud VS Code). Start the app with <code>npm start</code>.</p>","hand":true},{"id":"angular-f0003","card":"q-angular-001-1-course-app-prerequisites-and-project-s","sec":"angular-s002","q":"What does Codespaces port forwarding need for the Angular dev server?","a":"<p>The host must be bound to <code>0.0.0.0</code> with the host check disabled. This is set in the <code>start</code> script in <code>package.json</code>.</p>","hand":true},{"id":"angular-f0004","card":"q-angular-001-1-course-app-prerequisites-and-project-s","sec":"angular-s002","q":"What is the example app in the Angular course and what does it contain?","a":"<p><strong>Gem Finder</strong>. It has an All Players page (search by name), a Profile page (score, gems, ID), Leaderboards (top 5 scores and gem counts), a Message inbox (unread, delete), and routing with page titles and browser history.</p>","hand":true},{"id":"angular-f0005","card":"q-angular-001-1-course-app-prerequisites-and-project-s","sec":"angular-s002","q":"What is <code>app-root</code> in <code>index.html</code> of an Angular app?","a":"<p>It is the element where Angular mounts the app. The name is a convention.</p>","hand":true},{"id":"angular-f0006","card":"q-angular-001-1-course-app-prerequisites-and-project-s","sec":"angular-s002","q":"What do Bootstrap CSS, <code>styles.css</code> and <code>assets/mocks/</code> do in the Angular course app?","a":"<p>Bootstrap CSS is optional styling. <code>styles.css</code> holds global styles. JSON files in <code>assets/mocks/</code> stand in for a backend.</p>","hand":true},{"id":"angular-f0007","card":"q-angular-001-1-course-app-prerequisites-and-project-s","sec":"angular-s002","q":"What do the four root files of an Angular project do: <code>angular.json</code>, <code>package.json</code>, <code>tsconfig.json</code>, <code>.eslintrc.json</code>?","a":"<ul>\n  <li><code>angular.json</code>: CLI config</li>\n  <li><code>package.json</code>: deps and scripts</li>\n  <li><code>tsconfig.json</code>: TypeScript</li>\n  <li><code>.eslintrc.json</code>: lint rules</li>\n</ul>","hand":true},{"id":"angular-f0008","card":"q-angular-001-1-course-app-prerequisites-and-project-s","sec":"angular-s002","q":"What is the folder layout of <code>src/</code> in the Angular course app?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Text</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>src/\n├── index.html            # contains &lt;app-root&gt;\n├── main.ts               # bootstrap\n├── styles.css            # global styles\n├── app/\n│   ├── components/       # reusable components\n│   ├── pages/            # routed page components\n│   ├── services/         # business logic\n│   ├── pipes/\n│   ├── directives/\n│   └── interfaces/\n└── assets/mocks/         # mock JSON data</code></pre></div>","hand":true},{"id":"angular-f0009","card":"q-angular-001-1-course-app-prerequisites-and-project-s","sec":"angular-s002","q":"How does <code>main.ts</code> bootstrap a module-based Angular app?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>platformBrowserDynamic().bootstrapModule(AppModule)\n  .catch(err =&gt; console.error(err));</code></pre></div>","hand":true},{"id":"angular-f0010","card":"q-angular-001-1-course-app-prerequisites-and-project-s","sec":"angular-s002","q":"What does the root <code>AppModule</code> look like in the course app?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@NgModule({\n  declarations: [AppComponent],\n  imports: [BrowserModule, HttpClientModule, AppRoutingModule],\n  bootstrap: [AppComponent]\n})\nexport class AppModule { }</code></pre></div>","hand":true},{"id":"angular-f0011","card":"q-angular-001-1-course-app-prerequisites-and-project-s","sec":"angular-s002","q":"Why does the root <code>AppComponent</code> inject <code>MessageService</code> as <code>public</code>?","a":"<p>So the template can read it.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>constructor(public messageService: MessageService) { }</code></pre></div>","hand":true},{"id":"angular-f0012","card":"q-angular-002-2-angular-overview-versioning-license-to","sec":"angular-s003","q":"What is Angular's philosophy?","a":"<p>It keeps HTML templates separate from JavaScript controllers and extends HTML with custom attributes and dynamic content.</p>","hand":true},{"id":"angular-f0013","card":"q-angular-002-2-angular-overview-versioning-license-to","sec":"angular-s003","q":"Why is Angular called a platform and not only a UI library?","a":"<p>It provides routing, standard libraries, reusable components and a scalable architecture.</p>","hand":true},{"id":"angular-f0014","card":"q-angular-002-2-angular-overview-versioning-license-to","sec":"angular-s003","q":"What kind of apps does Angular build?","a":"<p>Single-page applications (SPAs) that update content without a browser refresh.</p>","hand":true},{"id":"angular-f0015","card":"q-angular-002-2-angular-overview-versioning-license-to","sec":"angular-s003","q":"Who maintains Angular and under which license?","a":"<p>A full-time Google team plus an open-source community. It is MIT licensed.</p>","hand":true},{"id":"angular-f0016","card":"q-angular-003-release-and-support-semver","sec":"angular-s004","q":"Angular releases: how do major, minor and patch releases differ in cadence and content?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Release</th><th>Cadence</th><th>Content</th></tr></thead>\n    <tbody>\n      <tr><td>Major</td><td>every 6 months</td><td>big features, possible breaking changes, upgrade path provided</td></tr>\n      <tr><td>Minor</td><td>1-3 per major</td><td>smaller features, backwards compatible</td></tr>\n      <tr><td>Patch</td><td>weekly</td><td>bug and security fixes, low risk, upgrade quickly</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"angular-f0017","card":"q-angular-003-release-and-support-semver","sec":"angular-s004","q":"How long is each Angular major version supported?","a":"<p>18 months: 6 months <strong>active</strong> (minor + patch) plus 12 months <strong>LTS</strong> (patch only).</p>","hand":true},{"id":"angular-f0018","card":"q-angular-003-release-and-support-semver","sec":"angular-s004","q":"How do <code>@angular/*</code> package versions and the CLI version relate?","a":"<p>All <code>@angular/*</code> packages release together with matching versions. The CLI major matches the framework major.</p>","hand":true},{"id":"angular-f0019","card":"q-angular-003-release-and-support-semver","sec":"angular-s004","q":"How do you upgrade Angular?","a":"<p>Run <code>ng update</code>.</p>","hand":true},{"id":"angular-f0020","card":"q-angular-003-release-and-support-semver","sec":"angular-s004","q":"Which packages and versions appear in the <code>dependencies</code> of the course project?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JSON</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>{\n  &quot;dependencies&quot;: {\n    &quot;@angular/animations&quot;: &quot;^16.1.3&quot;,\n    &quot;@angular/common&quot;: &quot;^16.1.3&quot;,\n    &quot;@angular/compiler&quot;: &quot;^16.1.3&quot;,\n    &quot;@angular/core&quot;: &quot;^16.1.3&quot;,\n    &quot;@angular/router&quot;: &quot;^16.1.3&quot;,\n    &quot;rxjs&quot;: &quot;^7.8.1&quot;,\n    &quot;zone.js&quot;: &quot;^0.13.0&quot;\n  }\n}</code></pre></div>","hand":true},{"id":"angular-f0021","card":"q-angular-004-mit-license","sec":"angular-s005","q":"What does the MIT license allow?","a":"<p>Any use, commercial use and proprietary code. It is very permissive and about 165 words long.</p>","hand":true},{"id":"angular-f0022","card":"q-angular-004-mit-license","sec":"angular-s005","q":"What does the MIT license require, and what does it not give?","a":"<p>It requires keeping the copyright notice and license text. There is no warranty, and the holders are not liable.</p>","hand":true},{"id":"angular-f0023","card":"q-angular-004-mit-license","sec":"angular-s005","q":"Which licenses and bodies is the MIT license compatible with or approved by?","a":"<p>It is compatible with GPL and DFSG, and approved by FSF and OSI.</p>","hand":true},{"id":"angular-f0024","card":"q-angular-005-angular-cli-ng","sec":"angular-s006","q":"How do you install the Angular CLI?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>npm install -g @angular/cli</code></pre></div>","hand":true},{"id":"angular-f0025","card":"q-angular-005-angular-cli-ng","sec":"angular-s006","q":"Which <code>ng</code> commands build, serve, lint, test and upgrade an Angular app?","a":"<ul>\n  <li><code>ng build</code>: compile and build</li>\n  <li><code>ng serve</code>: dev server</li>\n  <li><code>ng lint</code></li>\n  <li><code>ng test</code></li>\n  <li><code>ng update</code>: upgrade</li>\n</ul>","hand":true},{"id":"angular-f0026","card":"q-angular-005-angular-cli-ng","sec":"angular-s006","q":"How do you generate a component and a service with the Angular CLI?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>ng generate component my-component\nng generate service my-service</code></pre></div>","hand":true},{"id":"angular-f0027","card":"q-angular-005-angular-cli-ng","sec":"angular-s006","q":"What are the <code>package.json</code> scripts of the course app, and what do the <code>start</code> flags do?","a":"<p>The <code>start</code> flags are for Codespaces:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JSON</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>{\n  &quot;scripts&quot;: {\n    &quot;ng&quot;: &quot;ng&quot;,\n    &quot;start&quot;: &quot;ng serve --host=0.0.0.0 --disable-host-check&quot;,\n    &quot;build&quot;: &quot;ng build&quot;,\n    &quot;test&quot;: &quot;ng test&quot;,\n    &quot;lint&quot;: &quot;ng lint&quot;\n  }\n}</code></pre></div>","hand":true},{"id":"angular-f0028","card":"q-angular-006-developer-tools","sec":"angular-s007","q":"What does the Angular Language Service do?","a":"<p>It gives editor completion and hints (VS Code etc.).</p>","hand":true},{"id":"angular-f0029","card":"q-angular-006-developer-tools","sec":"angular-s007","q":"What is Angular DevTools?","a":"<p>A browser extension for component inspection, debugging and profiling.</p>","hand":true},{"id":"angular-f0030","card":"q-angular-006-developer-tools","sec":"angular-s007","q":"What are Schematics in Angular?","a":"<p>Reusable code templates. They power <code>ng generate</code>.</p>","hand":true},{"id":"angular-f0031","card":"q-angular-006-developer-tools","sec":"angular-s007","q":"What is the Angular CLI's role among the developer tools?","a":"<p>Scaffolding, build and serve.</p>","hand":true},{"id":"angular-f0032","card":"q-angular-007-angular-json","sec":"angular-s008","q":"What does <code>angular.json</code> configure?","a":"<p>The CLI workspace. A workspace holds one or more projects, and each project has build targets (production and development by default; you can add or remove them).</p>","hand":true},{"id":"angular-f0033","card":"q-angular-007-angular-json","sec":"angular-s008","q":"What is the structure of the <code>build</code> target in <code>angular.json</code>?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JSON</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>{\n  &quot;projects&quot;: {\n    &quot;gem-finder&quot;: {\n      &quot;architect&quot;: {\n        &quot;build&quot;: {\n          &quot;options&quot;: {\n            &quot;outputPath&quot;: &quot;dist/gem-finder&quot;,\n            &quot;main&quot;: &quot;src/main.ts&quot;,\n            &quot;tsConfig&quot;: &quot;tsconfig.app.json&quot;\n          },\n          &quot;configurations&quot;: {\n            &quot;production&quot;: { &quot;outputHashing&quot;: &quot;all&quot; },\n            &quot;development&quot;: { &quot;optimization&quot;: false, &quot;sourceMap&quot;: true }\n          }\n        },\n        &quot;serve&quot;: { &quot;defaultConfiguration&quot;: &quot;development&quot; },\n        &quot;lint&quot;: { &quot;builder&quot;: &quot;@angular-eslint/builder:lint&quot; }\n      }\n    }\n  }\n}</code></pre></div>","hand":true},{"id":"angular-f0034","card":"q-angular-007-angular-json","sec":"angular-s008","q":"What do the production and development build configurations set in <code>angular.json</code>?","a":"<p>Production sets <code>outputHashing</code> to <code>all</code>. Development sets <code>optimization</code> to <code>false</code> and <code>sourceMap</code> to <code>true</code>. <code>serve</code> uses <code>development</code> by default.</p>","hand":true},{"id":"angular-f0035","card":"q-angular-008-decorators","sec":"angular-s009","q":"What is a decorator in Angular?","a":"<p>A function that returns a function. It is not Angular-specific, but Angular cannot be used without it. It supplies metadata that tells Angular what a class is and how to inject it.</p>","hand":true},{"id":"angular-f0036","card":"q-angular-008-decorators","sec":"angular-s009","q":"What is the syntax of a decorator?","a":"<p><code>@Name()</code> or <code>@Name(config)</code>. It starts with <code>@</code>, always has parentheses, and has <strong>no semicolon</strong>.</p>","hand":true},{"id":"angular-f0037","card":"q-angular-008-decorators","sec":"angular-s009","q":"What are the common decorator syntax mistakes in Angular?","a":"<p><code>@Component</code> (no parentheses), <code>@Component()</code> (missing required config), and <code>@Component({});</code> (semicolon).</p>","hand":true},{"id":"angular-f0038","card":"q-angular-008-decorators","sec":"angular-s009","q":"When does Angular report decorator syntax mistakes?","a":"<p>Modern Angular reports them at compile time (<code>ng build</code> / <code>ng serve</code>). Older versions failed at runtime.</p>","hand":true},{"id":"angular-f0039","card":"q-angular-008-decorators","sec":"angular-s009","q":"What does the <code>@NgModule</code> decorator look like with all its properties?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@NgModule({ declarations: [], imports: [], exports: [], providers: [], bootstrap: [] })\nexport class AppModule { }</code></pre></div>","hand":true},{"id":"angular-f0040","card":"q-angular-008-decorators","sec":"angular-s009","q":"What does a standalone <code>@Component</code> decorator with <code>OnPush</code> look like?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@Component({\n  selector: &#x27;app-high-scores&#x27;,\n  templateUrl: &#x27;./high-scores.component.html&#x27;,\n  styleUrls: [&#x27;./high-scores.component.css&#x27;],\n  standalone: true,\n  imports: [CommonModule],\n  changeDetection: ChangeDetectionStrategy.OnPush\n})\nexport class HighScoresComponent { }</code></pre></div>","hand":true},{"id":"angular-f0041","card":"q-angular-008-decorators","sec":"angular-s009","q":"How do you declare a service with <code>@Injectable</code> available app-wide?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@Injectable({ providedIn: &#x27;root&#x27; })\nexport class ApiService { }</code></pre></div>","hand":true},{"id":"angular-f0042","card":"q-angular-008-decorators","sec":"angular-s009","q":"How do you declare a standalone pipe and a standalone directive with decorators?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@Pipe({ name: &#x27;join&#x27;, standalone: true })\nexport class JoinPipe implements PipeTransform { }\n\n@Directive({ selector: &#x27;[appOnlineStatus]&#x27;, standalone: true })\nexport class OnlineStatusDirective { }</code></pre></div>","hand":true},{"id":"angular-f0043","card":"q-angular-008-decorators","sec":"angular-s009","q":"How are <code>@Input</code> and <code>@Output</code> property decorators written?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@Input() public appOnlineStatus: boolean | undefined;\n@Output() public valueChange = new EventEmitter&lt;string&gt;();</code></pre></div>","hand":true},{"id":"angular-f0044","card":"q-angular-009-modules-ngmodule","sec":"angular-s010","q":"What is an Angular module?","a":"<p>It groups closely related components, services, pipes and directives. Files are named <code>*.module.ts</code>.</p>","hand":true},{"id":"angular-f0045","card":"q-angular-009-modules-ngmodule","sec":"angular-s010","q":"What does standalone (Angular 14+) change about modules?","a":"<p>It lets you use components, directives and pipes without a module. Modules are still the norm in existing projects.</p>","hand":true},{"id":"angular-f0046","card":"q-angular-009-modules-ngmodule","sec":"angular-s010","q":"What does the body of a module class contain?","a":"<p>Nothing, it is empty. The decorator metadata does the work; the class only tells Angular what to load.</p>","hand":true},{"id":"angular-f0047","card":"q-angular-009-modules-ngmodule","sec":"angular-s010","q":"Which module has <code>bootstrap</code>, and how many modules should an app use?","a":"<p>Only the root module has <code>bootstrap</code> (usually one component). Use one root module plus feature modules.</p>","hand":true},{"id":"angular-f0048","card":"q-angular-009-modules-ngmodule","sec":"angular-s010","q":"What do the <code>NgModule</code> properties <code>declarations</code>, <code>imports</code>, <code>exports</code>, <code>providers</code> and <code>bootstrap</code> mean?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Property</th><th>Meaning</th></tr></thead>\n    <tbody>\n      <tr><td><code>declarations</code></td><td>components, directives, pipes owned by this module. Each can belong to <strong>one</strong> module only (compiler error otherwise)</td></tr>\n      <tr><td><code>imports</code></td><td>external modules whose exports are usable in this module's templates</td></tr>\n      <tr><td><code>exports</code></td><td>code made available to modules that import this one</td></tr>\n      <tr><td><code>providers</code></td><td>services for dependency injection. Rule: modules go in <code>imports</code>, services in <code>providers</code></td></tr>\n      <tr><td><code>bootstrap</code></td><td>component(s) to load at launch, root module only</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"angular-f0049","card":"q-angular-009-modules-ngmodule","sec":"angular-s010","q":"Are <code>exports</code>, <code>providers</code> and the other <code>NgModule</code> properties required?","a":"<p>No. They are optional and can be left out or set to empty arrays.</p>","hand":true},{"id":"angular-f0050","card":"q-angular-009-modules-ngmodule","sec":"angular-s010","q":"What does a feature module such as <code>PlayersModule</code> look like?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@NgModule({\n  declarations: [PlayersComponent],\n  imports: [CommonModule, OnlineStatusDirective, PlayersRoutingModule]\n})\nexport class PlayersModule { }</code></pre></div>","hand":true},{"id":"angular-f0051","card":"q-angular-009-modules-ngmodule","sec":"angular-s010","q":"What does the optional second argument to <code>bootstrapModule</code> do?","a":"<p>It sets global options such as view encapsulation and missing translation strategy.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>platformBrowserDynamic().bootstrapModule(AppModule, {\n  // global settings, e.g. view encapsulation\n})</code></pre></div>","hand":true},{"id":"angular-f0052","card":"q-angular-009-modules-ngmodule","sec":"angular-s010","q":"How does a routing module lazy-load one module and one standalone component?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const routes: Routes = [\n  { path: &#x27;players&#x27;, loadChildren: () =&gt; import(&#x27;./pages/players/players.module&#x27;).then(m =&gt; m.PlayersModule) },\n  { path: &#x27;messages&#x27;, loadComponent: () =&gt; import(&#x27;./pages/messages/messages.component&#x27;).then(m =&gt; m.MessagesComponent) }\n];\n\n@NgModule({\n  imports: [RouterModule.forRoot(routes)],\n  exports: [RouterModule]\n})\nexport class AppRoutingModule { }</code></pre></div>","hand":true},{"id":"angular-f0053","card":"q-angular-010-4-components","sec":"angular-s011","q":"What is an Angular component and what are its four parts?","a":"<p>The main building block of Angular. Its parts are an HTML <strong>template</strong>, CSS <strong>styles</strong>, a TypeScript <strong>class</strong> (behavior), and a <strong>selector</strong> (where it goes in the DOM).</p>","hand":true},{"id":"angular-f0054","card":"q-angular-010-4-components","sec":"angular-s011","q":"What are components used for, and where do they live?","a":"<p>Routed pages (<code>pages/</code>) and reusable UI pieces (<code>components/</code>). Both are written the same way.</p>","hand":true},{"id":"angular-f0055","card":"q-angular-010-4-components","sec":"angular-s011","q":"What files make up an Angular component, and how do you generate one?","a":"<p><code>*.component.ts</code>, <code>*.component.html</code>, <code>*.component.css</code> and <code>*.component.spec.ts</code>. Generate it with:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>ng generate component component-name</code></pre></div>","hand":true},{"id":"angular-f0056","card":"q-angular-010-4-components","sec":"angular-s011","q":"What does a typical component class look like, with <code>ngOnInit</code> and a template method?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@Component({\n  selector: &#x27;app-players&#x27;,\n  templateUrl: &#x27;./players.component.html&#x27;,\n  styleUrls: [&#x27;./players.component.css&#x27;]\n})\nexport class PlayersComponent implements OnInit {\n  public players$: Observable&lt;Player[] | undefined&gt; = of(undefined);\n\n  public ngOnInit(): void {                         // lifecycle hook\n    this.players$ = this.api.getAllPlayers$();\n  }\n\n  public update(text: string) {                     // method used by the template\n    this.players$ = this.api.getPlayersByName$(text);\n  }\n}</code></pre></div>","hand":true},{"id":"angular-f0057","card":"q-angular-010-4-components","sec":"angular-s011","q":"What are the naming conventions for an Angular component?","a":"<p>The class is PascalCase ending in <code>Component</code>. The selector is <code>app-</code> + kebab-case.</p>","hand":true},{"id":"angular-f0058","card":"q-angular-011-decorator-properties","sec":"angular-s012","q":"What rules apply to a component's <code>selector</code>?","a":"<p>It is the custom element name and must contain a dash (avoids clashes with HTML elements). Any valid CSS selector works. Convention: <code>app-</code> prefix, kebab-case.</p>","hand":true},{"id":"angular-f0059","card":"q-angular-011-decorator-properties","sec":"angular-s012","q":"<code>templateUrl</code> vs <code>template</code> in <code>@Component</code>?","a":"<p><code>templateUrl</code> is an external file (recommended). <code>template</code> is inline HTML. Use one, not both.</p>","hand":true},{"id":"angular-f0060","card":"q-angular-011-decorator-properties","sec":"angular-s012","q":"<code>styleUrls</code> vs <code>styles</code> in <code>@Component</code>?","a":"<p><code>styleUrls</code> takes external CSS files. <code>styles</code> takes an inline CSS array. These can be combined.</p>","hand":true},{"id":"angular-f0061","card":"q-angular-011-decorator-properties","sec":"angular-s012","q":"What do <code>standalone</code>, <code>imports</code>, <code>changeDetection</code>, <code>providers</code> and <code>encapsulation</code> do in <code>@Component</code>?","a":"<ul>\n  <li><code>standalone</code>, <code>imports</code>: standalone architecture</li>\n  <li><code>changeDetection</code>: <code>Default</code> or <code>OnPush</code></li>\n  <li><code>providers</code>: component-scoped DI providers</li>\n  <li><code>encapsulation</code>: style encapsulation mode</li>\n</ul>","hand":true},{"id":"angular-f0062","card":"q-angular-011-decorator-properties","sec":"angular-s012","q":"How do you write a component with an inline template and inline styles?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@Component({ template: &#x27;&lt;h1&gt;Players&lt;/h1&gt;&#x27;, styles: [&#x27;h1 { color: blue; }&#x27;] })   // inline form</code></pre></div>","hand":true},{"id":"angular-f0063","card":"q-angular-011-decorator-properties","sec":"angular-s012","q":"Do Angular components use Shadow DOM by default, and how do you opt in?","a":"<p>No, so global CSS reaches them. Opt in with:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@Component({ encapsulation: ViewEncapsulation.ShadowDom })</code></pre></div>","hand":true},{"id":"angular-f0064","card":"q-angular-012-template-reference-variable","sec":"angular-s013","q":"What does a template reference variable (<code>#name</code>) do?","a":"<p><code>#name</code> on an element gives the template access to that element's DOM data without passing it to the class.</p>","hand":true},{"id":"angular-f0065","card":"q-angular-012-template-reference-variable","sec":"angular-s013","q":"How can a template read an input's value without a class property, and call a component method on <code>keyup</code>?","a":"<p>Put <code>#filter</code> on the input and pass <code>filter.value</code>:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">HTML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>&lt;input type=&quot;text&quot; class=&quot;form-control&quot; placeholder=&quot;Find Players by Name&quot;\n       #filter (keyup)=&quot;update(filter.value)&quot;&gt;</code></pre></div>","hand":true},{"id":"angular-f0066","card":"q-angular-012-template-reference-variable","sec":"angular-s013","q":"How does a Clear button reset a search input in the template?","a":"<p>It calls <code>update('')</code> and sets <code>filter.value = ''</code>:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">HTML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>&lt;button class=&quot;btn btn-light&quot; type=&quot;button&quot;\n        (click)=&quot;update(&#x27;&#x27;); filter.value = &#x27;&#x27;&quot;&gt;Clear&lt;/button&gt;</code></pre></div>","hand":true},{"id":"angular-f0067","card":"q-angular-012-template-reference-variable","sec":"angular-s013","q":"How does the players template render a list with a loading fallback?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">HTML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>&lt;ul *ngIf=&quot;players$ | async as players; else loading&quot; class=&quot;my-4&quot;&gt;\n  &lt;li *ngFor=&quot;let player of players&quot; [appOnlineStatus]=&quot;player.online&quot;&gt;\n    &lt;a [routerLink]=&quot;[&#x27;/profile&#x27;, player.id]&quot;&gt;{{ player.name }}&lt;/a&gt;\n  &lt;/li&gt;\n&lt;/ul&gt;\n\n&lt;ng-template #loading&gt;\n  &lt;p class=&quot;my-4&quot;&gt;Loading&amp;hellip;&lt;/p&gt;\n&lt;/ng-template&gt;</code></pre></div>","hand":true},{"id":"angular-f0068","card":"q-angular-013-three-binding-types","sec":"angular-s014","q":"What are the three binding types in Angular templates?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Type</th><th>Syntax</th><th>Use</th></tr></thead>\n    <tbody>\n      <tr><td>Event</td><td><code>(event)=\"action\"</code></td><td>run code on <code>click</code>, <code>keyup</code>, <code>submit</code>, <code>change</code></td></tr>\n      <tr><td>Property</td><td><code>[property]=\"value\"</code></td><td>assign attributes, directive inputs or component inputs at runtime</td></tr>\n      <tr><td>Interpolation</td><td><code>{{ expression }}</code></td><td>display a value as text</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"angular-f0069","card":"q-angular-013-three-binding-types","sec":"angular-s014","q":"Which binding is <code>(click)=\"action\"</code> and what is it for?","a":"<p>Event binding. It runs code on <code>click</code>, <code>keyup</code>, <code>submit</code>, <code>change</code>.</p>","hand":true},{"id":"angular-f0070","card":"q-angular-013-three-binding-types","sec":"angular-s014","q":"Which binding is <code>[property]=\"value\"</code> and what is it for?","a":"<p>Property binding. It assigns attributes, directive inputs or component inputs at runtime.</p>","hand":true},{"id":"angular-f0071","card":"q-angular-013-three-binding-types","sec":"angular-s014","q":"Which binding is <code>{{ expression }}</code> and what is it for?","a":"<p>Interpolation. It displays a value as text.</p>","hand":true},{"id":"angular-f0072","card":"q-angular-013-three-binding-types","sec":"angular-s014","q":"Show a template that uses interpolation with a pipe and property binding with a directive input.","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">HTML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>&lt;span&gt;{{ player.score | percent : &#x27;1.1-1&#x27; }}&lt;/span&gt;\n&lt;dd class=&quot;lead&quot;&gt;{{ player.gems | join }}&lt;/dd&gt;\n&lt;h2 [appOnlineStatus]=&quot;player.online&quot;&gt;Profile for {{ player.id }}&lt;/h2&gt;</code></pre></div>","hand":true},{"id":"angular-f0073","card":"q-angular-014-structural-directives","sec":"angular-s015","q":"What are structural directives in Angular?","a":"<p>Directives that start with <code>*</code> and <strong>add or remove elements</strong> from the DOM (not CSS hide/show).</p>","hand":true},{"id":"angular-f0074","card":"q-angular-014-structural-directives","sec":"angular-s015","q":"What does <code>*ngIf=\"cond\"</code> do, and what does <code>else templateRef</code> do?","a":"<p><code>*ngIf</code> renders the element when the condition is truthy. <code>else templateRef</code> renders the alternate when it is falsy.</p>","hand":true},{"id":"angular-f0075","card":"q-angular-014-structural-directives","sec":"angular-s015","q":"How do you unwrap an observable into a local variable with <code>*ngIf</code>?","a":"<p>Use <code>*ngIf=\"obs$ | async as value\"</code>.</p>","hand":true},{"id":"angular-f0076","card":"q-angular-014-structural-directives","sec":"angular-s015","q":"What does <code>*ngFor=\"let item of items\"</code> do?","a":"<p>It repeats an element per array item.</p>","hand":true},{"id":"angular-f0077","card":"q-angular-014-structural-directives","sec":"angular-s015","q":"What is <code>&lt;ng-template #name&gt;</code> for?","a":"<p>It holds content that does not render unless a trigger (such as <code>else</code>) asks for it.</p>","hand":true},{"id":"angular-f0078","card":"q-angular-014-structural-directives","sec":"angular-s015","q":"What renders in the players template when <code>players$</code> is <code>of(undefined)</code> and when it is <code>this.api.getAllPlayers$()</code>?","a":"<p>With <code>of(undefined)</code> the <code>loading</code> template renders. With <code>this.api.getAllPlayers$()</code> the <code>&lt;ul&gt;</code> renders.</p>","hand":true},{"id":"angular-f0079","card":"q-angular-014-structural-directives","sec":"angular-s015","q":"How do you compose a page from components in a template?","a":"<p>Use each component's selector as an element:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">HTML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>&lt;app-high-scores&gt;&lt;/app-high-scores&gt;\n&lt;app-most-gems&gt;&lt;/app-most-gems&gt;</code></pre></div>","hand":true},{"id":"angular-f0080","card":"q-angular-015-standalone-angular-14","sec":"angular-s016","q":"What is a standalone component, directive or pipe?","a":"<p>One you use without assigning it to a module. It gives a simpler structure and is compatible with module-based code, so migration can be gradual.</p>","hand":true},{"id":"angular-f0081","card":"q-angular-015-standalone-angular-14","sec":"angular-s016","q":"How do you make a component, pipe or directive standalone, and what is the default?","a":"<p>Set <code>standalone: true</code>. The default is <code>false</code> as of Angular 16.</p>","hand":true},{"id":"angular-f0082","card":"q-angular-015-standalone-angular-14","sec":"angular-s016","q":"Where does a standalone piece get its imports from?","a":"<p>It declares its own <code>imports</code> (built-in <code>CommonModule</code>, other standalone pieces, router directives, pipe modules) and optional <code>providers</code>. Imports are <strong>not</strong> inherited from a module.</p>","hand":true},{"id":"angular-f0083","card":"q-angular-015-standalone-angular-14","sec":"angular-s016","q":"How do you generate a standalone component with the CLI?","a":"<p>Run <code>ng generate component component-name --standalone</code>.</p>","hand":true},{"id":"angular-f0084","card":"q-angular-015-standalone-angular-14","sec":"angular-s016","q":"What does a standalone component with imports, providers and OnPush look like?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@Component({\n  selector: &#x27;app-high-scores&#x27;,\n  templateUrl: &#x27;./high-scores.component.html&#x27;,\n  styleUrls: [&#x27;./high-scores.component.css&#x27;],\n  standalone: true,\n  imports: [CommonModule, OnlineStatusDirective, RouterLinkWithHref, SortByScoreModule],\n  providers: [],\n  changeDetection: ChangeDetectionStrategy.OnPush\n})\nexport class HighScoresComponent implements OnInit {\n  public players$: Observable&lt;Player[] | undefined&gt; = of(undefined);\n  constructor(private api: ApiService) { }\n  public ngOnInit(): void {\n    this.players$ = this.api.getAllPlayers$();\n  }\n}</code></pre></div>","hand":true},{"id":"angular-f0085","card":"q-angular-015-standalone-angular-14","sec":"angular-s016","q":"What does a standalone pipe that sorts players by gem count look like?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@Pipe({ name: &#x27;sortByGemCount&#x27;, standalone: true })\nexport class SortByGemCountPipe implements PipeTransform {\n  transform(value: Player[]): Player[] {\n    return value.sort((a, b) =&gt; b.gems.length - a.gems.length);\n  }\n}</code></pre></div>","hand":true},{"id":"angular-f0086","card":"q-angular-015-standalone-angular-14","sec":"angular-s016","q":"How do you migrate a component from modules to standalone, in short?","a":"<p>Declare it in a module before, and mark it <code>standalone: true</code> with its own <code>imports</code> after:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>// Module-based\n@NgModule({ declarations: [MyComponent], imports: [CommonModule] })\n// Standalone\n@Component({ standalone: true, imports: [CommonModule] })</code></pre></div>","hand":true},{"id":"angular-f0087","card":"q-angular-015-standalone-angular-14","sec":"angular-s016","q":"What is the recommended path for migrating to standalone?","a":"<p>Start with new or simple components, update module imports, test, and continue incrementally. Keep modules where a large codebase or complex dependency structure makes migration costly.</p>","hand":true},{"id":"angular-f0088","card":"q-angular-015-standalone-angular-14","sec":"angular-s016","q":"Which route property lazy-loads a standalone component and which lazy-loads a module?","a":"<p><code>loadComponent</code> for standalone, <code>loadChildren</code> for modules.</p>","hand":true},{"id":"angular-f0089","card":"q-angular-016-using-standalone-pieces-inside-a-module","sec":"angular-s017","q":"Where do standalone components, directives and pipes go in an <code>NgModule</code>?","a":"<p>In the module's <code>imports</code>, never in <code>declarations</code>.</p>","hand":true},{"id":"angular-f0090","card":"q-angular-016-using-standalone-pieces-inside-a-module","sec":"angular-s017","q":"What does a module that uses a standalone component, directive and pipe look like?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@NgModule({\n  declarations: [LeaderboardsComponent, MostGemsComponent],\n  imports: [\n    CommonModule,\n    HighScoresComponent,        // standalone component\n    LeaderboardsRoutingModule,\n    OnlineStatusDirective,      // standalone directive\n    SortByGemCountPipe          // standalone pipe\n  ]\n})\nexport class LeaderboardsModule { }</code></pre></div>","hand":true},{"id":"angular-f0091","card":"q-angular-017-testing-a-standalone-component","sec":"angular-s018","q":"Where does a standalone component go in <code>TestBed.configureTestingModule</code>?","a":"<p>In <code>imports</code>, not <code>declarations</code>. Use <code>provide*</code> functions for dependencies.</p>","hand":true},{"id":"angular-f0092","card":"q-angular-017-testing-a-standalone-component","sec":"angular-s018","q":"How do you set up a test for a standalone component that makes API calls?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>beforeEach(async () =&gt; {\n  await TestBed.configureTestingModule({\n    imports: [HighScoresComponent],\n    providers: [\n      provideHttpClient(),\n      provideHttpClientTesting()   // mock API calls\n    ]\n  }).compileComponents();\n\n  fixture = TestBed.createComponent(HighScoresComponent);\n  component = fixture.componentInstance;\n  fixture.detectChanges();\n});</code></pre></div>","hand":true},{"id":"angular-f0093","card":"q-angular-017-testing-a-standalone-component","sec":"angular-s018","q":"What is the basic \"should create\" spec for a component?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>it(&#x27;should create&#x27;, () =&gt; {\n  expect(component).toBeTruthy();\n});</code></pre></div>","hand":true},{"id":"angular-f0094","card":"q-angular-017-testing-a-standalone-component","sec":"angular-s018","q":"Which provider helper follows the same pattern as <code>provideHttpClient()</code> for router dependencies in tests?","a":"<p><code>provideRouter()</code>.</p>","hand":true},{"id":"angular-f0095","card":"q-angular-018-zoneless-angular-18","sec":"angular-s019","q":"What is zoneless Angular?","a":"<p>An architecture without ZoneJS. It was experimental and opt-in at the time of the course, with an incomplete, unstable API.</p>","hand":true},{"id":"angular-f0096","card":"q-angular-018-zoneless-angular-18","sec":"angular-s019","q":"What are the benefits of zoneless Angular?","a":"<p>Fewer change detection cycles, smaller bundles, faster startup, better debugging, and better third-party API compatibility.</p>","hand":true},{"id":"angular-f0097","card":"q-angular-018-zoneless-angular-18","sec":"angular-s019","q":"What are the risks of zoneless Angular?","a":"<p>The API can change, and it may require dependency, code and unit-test changes.</p>","hand":true},{"id":"angular-f0098","card":"q-angular-018-zoneless-angular-18","sec":"angular-s019","q":"Should you adopt zoneless Angular in new or existing projects?","a":"<p>Try it on new projects. Wait for stability on existing ones.</p>","hand":true},{"id":"angular-f0099","card":"q-angular-019-7-pipes","sec":"angular-s020","q":"What are pipes in Angular and do built-in pipes need imports?","a":"<p>Pipes transform data inside templates. Files are <code>*.pipe.ts</code>. Built-in pipes need no imports.</p>","hand":true},{"id":"angular-f0100","card":"q-angular-019-7-pipes","sec":"angular-s020","q":"What is the template syntax for a pipe with arguments, and for chaining pipes?","a":"<p>Arguments are separated by colons. Chained pipes run left to right and each output feeds the next:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">HTML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>{{ value | pipeName }}\n{{ value | pipeName : arg1 : arg2 }}      &lt;!-- arguments separated by colons --&gt;\n{{ value | pipe1 | pipe2 | pipe3 }}       &lt;!-- chained left to right; each output feeds the next --&gt;</code></pre></div>","hand":true},{"id":"angular-f0101","card":"q-angular-020-built-in-pipes","sec":"angular-s021","q":"What does the <code>slice : start : end</code> pipe do?","a":"<p>It works like JavaScript <code>slice</code>. For an array, <code>slice : 0 : 5</code> gives the first 5 items.</p>","hand":true},{"id":"angular-f0102","card":"q-angular-020-built-in-pipes","sec":"angular-s021","q":"What does the <code>percent : 'minInt.minFrac-maxFrac'</code> pipe do, and what does <code>'1.1-1'</code> mean?","a":"<p>It formats a number as a percentage with the browser locale. <code>'1.1-1'</code> means min 1 integer digit, min 1 and max 1 fraction digit.</p>","hand":true},{"id":"angular-f0103","card":"q-angular-020-built-in-pipes","sec":"angular-s021","q":"What do <code>{{ 0.5 | percent : '1.1-1' }}</code>, <code>'3.1-1'</code> and <code>'1.4-5'</code> display?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">HTML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>{{ 0.5 | percent : &#x27;1.1-1&#x27; }}   &lt;!-- 50.0% --&gt;\n{{ 0.5 | percent : &#x27;3.1-1&#x27; }}   &lt;!-- 050.0% --&gt;\n{{ 0.5 | percent : &#x27;1.4-5&#x27; }}   &lt;!-- 50.0000% --&gt;</code></pre></div>","hand":true},{"id":"angular-f0104","card":"q-angular-020-built-in-pipes","sec":"angular-s021","q":"What does the <code>number</code> pipe do, and what other built-in pipes exist?","a":"<p><code>number</code> adds locale thousands separators. Others: <code>uppercase</code>, <code>lowercase</code>, <code>titlecase</code>, <code>json</code>, <code>currency</code>, <code>date</code>.</p>","hand":true},{"id":"angular-f0105","card":"q-angular-020-built-in-pipes","sec":"angular-s021","q":"How do you format a date with a built-in pipe?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">HTML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>{{ date | date : &#x27;short&#x27; : &#x27;UTC&#x27; }}</code></pre></div>","hand":true},{"id":"angular-f0106","card":"q-angular-020-built-in-pipes","sec":"angular-s021","q":"What does the built-in <code>async</code> pipe do?","a":"<p>It subscribes to a Promise/Observable and unsubscribes automatically.</p>","hand":true},{"id":"angular-f0107","card":"q-angular-021-custom-pipes","sec":"angular-s022","q":"How do you generate a custom pipe?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>ng generate pipe pipe-name</code></pre></div>","hand":true},{"id":"angular-f0108","card":"q-angular-021-custom-pipes","sec":"angular-s022","q":"What are the requirements of a custom pipe class?","a":"<p>It is decorated with <code>@Pipe</code>, implements <code>PipeTransform</code>, ends in <code>Pipe</code>, and has a <code>transform</code> method (build error if missing). The first argument is the template value, extra arguments are pipe arguments, and it must return a value.</p>","hand":true},{"id":"angular-f0109","card":"q-angular-021-custom-pipes","sec":"angular-s022","q":"What are the <code>@Pipe</code> properties <code>name</code>, <code>pure</code> and <code>standalone</code>?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Property</th><th>Notes</th></tr></thead>\n    <tbody>\n      <tr><td><code>name</code></td><td>camelCase, no hyphens (build error)</td></tr>\n      <tr><td><code>pure</code></td><td>default <code>true</code>: runs only when the input reference changes (fast). <code>false</code> runs on every change detection cycle, so use sparingly</td></tr>\n      <tr><td><code>standalone</code></td><td><code>true</code> for standalone architecture, <code>false</code> for module architecture</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"angular-f0110","card":"q-angular-021-custom-pipes","sec":"angular-s022","q":"What does a module-based custom pipe look like?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@Pipe({ name: &#x27;sortByScore&#x27;, pure: true, standalone: false })\nexport class SortByScorePipe implements PipeTransform {\n  transform(players: Player[]): Player[] {\n    return players.sort((a, b) =&gt; b.score - a.score);\n  }\n}</code></pre></div>","hand":true},{"id":"angular-f0111","card":"q-angular-021-custom-pipes","sec":"angular-s022","q":"How does a module share a custom pipe with other modules?","a":"<p>It lists the pipe in <code>declarations</code> and <code>exports</code>. Consumers import <code>SortByScoreModule</code> (in a module or a standalone component's <code>imports</code>).</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@NgModule({\n  declarations: [SortByScorePipe],\n  imports: [CommonModule],\n  exports: [SortByScorePipe]          // export so other modules can use it\n})\nexport class SortByScoreModule { }</code></pre></div>","hand":true},{"id":"angular-f0112","card":"q-angular-021-custom-pipes","sec":"angular-s022","q":"How do you write a standalone <code>join</code> pipe with a default argument, and how is it used?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@Pipe({ name: &#x27;join&#x27;, standalone: true })\nexport class JoinPipe implements PipeTransform {\n  transform&lt;T extends unknown[]&gt;(value: T, separator = &#x27;, &#x27;): string {\n    return value.join(separator);\n  }\n}</code></pre></div>\n<p>Usage:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">HTML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>{{ player.gems | join }}\n{{ player.gems | join : &#x27; - &#x27; }}</code></pre></div>","hand":true},{"id":"angular-f0113","card":"q-angular-021-custom-pipes","sec":"angular-s022","q":"What is the generic signature of a pipe's <code>transform</code> method, and how does one with explicit arguments look?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>transform(value: any, ...args: any[]): any { return transformedValue; }\n\ntransform(value: Player[], start: number, end: number): Player[] {\n  return value.slice(start, end);\n}</code></pre></div>","hand":true},{"id":"angular-f0114","card":"q-angular-021-custom-pipes","sec":"angular-s022","q":"How do you combine pipes in a template to show the top 5 players by gem count?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">HTML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>&lt;li *ngFor=&quot;let player of players | sortByGemCount | slice : 0 : 5&quot; [appOnlineStatus]=&quot;player.online&quot;&gt;</code></pre></div>\n<p>The gem count is shown with <code>{{ player.gems.length | number }}</code>.</p>","hand":true},{"id":"angular-f0115","card":"q-angular-021-custom-pipes","sec":"angular-s022","q":"What are the design rules for custom pipes?","a":"<p>One job per pipe, easy to test and chain, one pipe per file.</p>","hand":true},{"id":"angular-f0116","card":"q-angular-022-8-services","sec":"angular-s023","q":"What are Angular services for?","a":"<p>They separate and reuse code: API calls, calculations, business logic, anything that does not change the UI directly. They keep components small. Files are <code>*.service.ts</code>.</p>","hand":true},{"id":"angular-f0117","card":"q-angular-022-8-services","sec":"angular-s023","q":"How do you generate a service?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>ng generate service service-name</code></pre></div>","hand":true},{"id":"angular-f0118","card":"q-angular-022-8-services","sec":"angular-s023","q":"What does <code>@Injectable({ providedIn: 'root' })</code> do?","a":"<p>It creates one <strong>singleton</strong> for the whole app, so every consumer sees the same data (caching, shared state). It is the CLI default.</p>","hand":true},{"id":"angular-f0119","card":"q-angular-022-8-services","sec":"angular-s023","q":"What happens with <code>providedIn: null</code> or a bare <code>@Injectable()</code>?","a":"<p>You must add the service to a <code>providers</code> array.</p>","hand":true},{"id":"angular-f0120","card":"q-angular-023-canonical-http-service","sec":"angular-s024","q":"What does the canonical <code>ApiService</code> with <code>HttpClient</code> look like?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@Injectable({ providedIn: &#x27;root&#x27; })\nexport class ApiService {\n  constructor(private http: HttpClient) { }\n\n  public getAllPlayers$() {\n    return this.http.get&lt;Player[]&gt;(&#x27;/assets/mocks/players.json&#x27;).pipe(delay(1000));\n  }\n\n  public getPlayerById$(id: string) {\n    return this.getAllPlayers$().pipe(\n      map(players =&gt; players.find(player =&gt; player.id === id))\n    );\n  }\n\n  public getPlayersByName$(text: string) {\n    return this.getAllPlayers$().pipe(\n      map(players =&gt; players.filter(player =&gt;\n        player.name.toLowerCase().includes(text.toLowerCase())\n      ))\n    );\n  }\n}</code></pre></div>","hand":true},{"id":"angular-f0121","card":"q-angular-023-canonical-http-service","sec":"angular-s024","q":"Which access modifier should a service constructor use for injected dependencies?","a":"<p><code>private</code> is recommended (easy to spot dead code). Use <code>public</code> if the template needs it, and <code>protected</code> for subclasses.</p>","hand":true},{"id":"angular-f0122","card":"q-angular-023-canonical-http-service","sec":"angular-s024","q":"What must a module-based app import to use <code>HttpClient</code>?","a":"<p><code>HttpClientModule</code> in <code>AppModule.imports</code>.</p>","hand":true},{"id":"angular-f0123","card":"q-angular-023-canonical-http-service","sec":"angular-s024","q":"What does the <code>$</code> suffix mean on a method or property name?","a":"<p>It marks observable-returning methods or properties. It is a convention, not required.</p>","hand":true},{"id":"angular-f0124","card":"q-angular-023-canonical-http-service","sec":"angular-s024","q":"What does <code>http.get&lt;Type&gt;(url, options?)</code> do and why use the generic?","a":"<p>The URL is local or remote. The generic gives type safety and autocomplete.</p>","hand":true},{"id":"angular-f0125","card":"q-angular-023-canonical-http-service","sec":"angular-s024","q":"What do <code>.pipe(...)</code>, <code>delay</code> and <code>map</code> do in an HTTP service?","a":"<p><code>.pipe(...)</code> composes operators. <code>delay</code> simulates network lag, <code>map</code> transforms the data.</p>","hand":true},{"id":"angular-f0126","card":"q-angular-023-canonical-http-service","sec":"angular-s024","q":"Should a service return observables or subscribe itself?","a":"<p>It returns observables and lets components (or the <code>async</code> pipe) subscribe.</p>","hand":true},{"id":"angular-f0127","card":"q-angular-023-canonical-http-service","sec":"angular-s024","q":"What naming rule applies to service classes?","a":"<p>The class name ends in <code>Service</code>.</p>","hand":true},{"id":"angular-f0128","card":"q-angular-024-other-service-shapes","sec":"angular-s025","q":"What does a utility service without HTTP look like?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@Injectable({ providedIn: &#x27;root&#x27; })\nexport class AnalyticsService {\n  public track(key: string, value: string) {\n    sessionStorage.setItem(key, value);\n  }\n}</code></pre></div>","hand":true},{"id":"angular-f0129","card":"q-angular-024-other-service-shapes","sec":"angular-s025","q":"How does <code>MessageService</code> combine signals, an injected service and an HTTP call in the constructor?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@Injectable({ providedIn: &#x27;root&#x27; })\nexport class MessageService {\n  public unread = signal&lt;Message[]&gt;([]);\n\n  public count = computed(() =&gt; {\n    return this.unread().length;\n  });\n\n  constructor(\n    private analytics: AnalyticsService,\n    private http: HttpClient,\n  ) {\n    effect(() =&gt; {\n      this.analytics.track(&#x27;MESSAGE_COUNT&#x27;, this.count().toString());\n    });\n\n    this.http\n      .get&lt;Message[]&gt;(&#x27;/assets/mocks/messages.json&#x27;)\n      .pipe(takeUntilDestroyed())\n      .subscribe({\n        next: items =&gt; this.unread.set(items)\n      });\n  }\n\n  public delete(selected: Message) {\n    this.unread.update(items =&gt; {\n      return items.filter((item) =&gt; item.id !== selected.id);\n    });\n  }\n}</code></pre></div>","hand":true},{"id":"angular-f0130","card":"q-angular-024-other-service-shapes","sec":"angular-s025","q":"What does a generic CRUD API service look like?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@Injectable({ providedIn: &#x27;root&#x27; })\nexport class ApiService {\n  constructor(private http: HttpClient) { }\n  getAll$()                   { return this.http.get&lt;T[]&gt;(url); }\n  getById$(id: string)        { return this.http.get&lt;T&gt;(url); }\n  create$(data: T)            { return this.http.post&lt;T&gt;(url, data); }\n  update$(id: string, data: T){ return this.http.put&lt;T&gt;(url, data); }\n  delete$(id: string)         { return this.http.delete(url); }\n}</code></pre></div>","hand":true},{"id":"angular-f0131","card":"q-angular-024-other-service-shapes","sec":"angular-s025","q":"What does a signal-based state service look like?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@Injectable({ providedIn: &#x27;root&#x27; })\nexport class StateService {\n  private state = signal&lt;State&gt;(initialState);\n  public readonly state$ = this.state.asReadonly();\n  public updateState(newState: State) { this.state.set(newState); }\n}</code></pre></div>","hand":true},{"id":"angular-f0132","card":"q-angular-025-injecting-services","sec":"angular-s026","q":"How do you inject a service into a component?","a":"<p>Import the service, inject it as a private constructor member, and call its methods. Services can also inject other services.</p>","hand":true},{"id":"angular-f0133","card":"q-angular-025-injecting-services","sec":"angular-s026","q":"How do you inject several services in one constructor?","a":"<p>List them in the constructor:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>constructor(\n  private api: ApiService,\n  private analytics: AnalyticsService,\n  private router: Router\n) { }</code></pre></div>","hand":true},{"id":"angular-f0134","card":"q-angular-025-injecting-services","sec":"angular-s026","q":"What are use cases for singleton services?","a":"<p>Shared state, cached data, global configuration and authentication state.</p>","hand":true},{"id":"angular-f0135","card":"q-angular-026-9-directives","sec":"angular-s027","q":"What do Angular directives do?","a":"<p>They attach custom behavior to elements: add HTML, change appearance, add listeners. Files are <code>*.directive.ts</code>.</p>","hand":true},{"id":"angular-f0136","card":"q-angular-026-9-directives","sec":"angular-s027","q":"How do you generate a directive?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>ng generate directive directive-name</code></pre></div>","hand":true},{"id":"angular-f0137","card":"q-angular-026-9-directives","sec":"angular-s027","q":"What are the <code>@Directive</code> properties?","a":"<p><code>selector</code> (the attribute selector <code>[appName]</code> is the common form; prefix with <code>app</code>), optional <code>providers</code>, and <code>standalone</code> (<code>true</code> for standalone, <code>false</code> or left out for modules).</p>","hand":true},{"id":"angular-f0138","card":"q-angular-027-full-directive","sec":"angular-s028","q":"What does the full <code>OnlineStatusDirective</code> look like?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@Directive({\n  selector: &#x27;[appOnlineStatus]&#x27;,\n  providers: [],\n  standalone: true\n})\nexport class OnlineStatusDirective implements AfterContentInit {\n  @Input() public appOnlineStatus: boolean | undefined;\n\n  constructor(private element: ElementRef&lt;HTMLAnchorElement&gt;) { }\n\n  public ngAfterContentInit(): void {\n    if (this.appOnlineStatus === true) {\n      this.element.nativeElement.innerHTML += &#x27;&lt;i class=&quot;bi bi-lightning-fill&quot;&gt;&lt;/i&gt;&#x27;;\n    }\n  }\n}</code></pre></div>","hand":true},{"id":"angular-f0139","card":"q-angular-027-full-directive","sec":"angular-s028","q":"How do you apply <code>OnlineStatusDirective</code> in a template?","a":"<p>Bind it as a property on the element:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">HTML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>&lt;li *ngFor=&quot;let player of players&quot; [appOnlineStatus]=&quot;player.online&quot;&gt;\n  &lt;a [routerLink]=&quot;[&#x27;/profile&#x27;, player.id]&quot;&gt;{{ player.name }}&lt;/a&gt;\n&lt;/li&gt;</code></pre></div>","hand":true},{"id":"angular-f0140","card":"q-angular-027-full-directive","sec":"angular-s028","q":"What does <code>@Input</code> do in a directive, and what is an alias?","a":"<p>It receives a value from the parent through binding. The simplest pattern is that the property name equals the selector name. The alias form is <code>@Input('customName') public appOnlineStatus: boolean;</code>.</p>","hand":true},{"id":"angular-f0141","card":"q-angular-027-full-directive","sec":"angular-s028","q":"What is <code>ElementRef&lt;T&gt;.nativeElement</code>?","a":"<p>The underlying DOM element, injected via the constructor.</p>","hand":true},{"id":"angular-f0142","card":"q-angular-027-full-directive","sec":"angular-s028","q":"Why does the directive implement <code>AfterContentInit</code>?","a":"<p>It guarantees Angular has initialized content before the code runs, so DOM edits are safe.</p>","hand":true},{"id":"angular-f0143","card":"q-angular-027-full-directive","sec":"angular-s028","q":"How many directive instances does Angular create for an element?","a":"<p><strong>One directive instance per element</strong>, each with its own <code>ElementRef</code>. Online players get the lightning icon, offline ones do not.</p>","hand":true},{"id":"angular-f0144","card":"q-angular-028-types-and-module-vs-standalone","sec":"angular-s029","q":"Attribute directives vs structural directives?","a":"<p><strong>Attribute directives</strong> change appearance or behavior (<code>[appOnlineStatus]</code>). <strong>Structural directives</strong> add or remove elements (<code>*ngIf</code>, <code>*ngFor</code>).</p>","hand":true},{"id":"angular-f0145","card":"q-angular-028-types-and-module-vs-standalone","sec":"angular-s029","q":"How is a directive declared in a module-based app vs a standalone app?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>// module-based\n@Directive({ selector: &#x27;[appOnlineStatus]&#x27;, standalone: false })\n@NgModule({ declarations: [OnlineStatusDirective], exports: [OnlineStatusDirective] })\n\n// standalone\n@Directive({ selector: &#x27;[appOnlineStatus]&#x27;, standalone: true })\n@Component({ imports: [OnlineStatusDirective] })</code></pre></div>","hand":true},{"id":"angular-f0146","card":"q-angular-029-elementref-vs-renderer2","sec":"angular-s030","q":"ElementRef vs Renderer2: which is safer and why?","a":"<p><code>Renderer2</code> is the recommended, safer API. Direct <code>nativeElement</code> access is less safe (XSS risk) and does not work with server-side rendering.</p>","hand":true},{"id":"angular-f0147","card":"q-angular-029-elementref-vs-renderer2","sec":"angular-s030","q":"How do you add an icon with <code>ElementRef</code> directly vs with <code>Renderer2</code>?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>// ElementRef (direct)\nthis.element.nativeElement.innerHTML += &#x27;&lt;i&gt;Icon&lt;/i&gt;&#x27;;\n\n// Renderer2\nconst icon = this.renderer.createElement(&#x27;i&#x27;);\nthis.renderer.appendChild(this.element.nativeElement, icon);</code></pre></div>","hand":true},{"id":"angular-f0148","card":"q-angular-029-elementref-vs-renderer2","sec":"angular-s030","q":"How do you listen to a host element's click in a directive?","a":"<p>Use <code>@HostListener</code>:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@Directive({ selector: &#x27;[appClickTracker]&#x27; })\nexport class ClickTrackerDirective {\n  @HostListener(&#x27;click&#x27;)\n  onClick() { console.log(&#x27;Element clicked&#x27;); }\n}</code></pre></div>","hand":true},{"id":"angular-f0149","card":"q-angular-029-elementref-vs-renderer2","sec":"angular-s030","q":"How do you write a safe highlight directive with <code>Renderer2</code>?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@Directive({ selector: &#x27;[appSafeHighlight]&#x27; })\nexport class SafeHighlightDirective {\n  constructor(private el: ElementRef, private renderer: Renderer2) { }\n  ngAfterContentInit() {\n    this.renderer.setStyle(this.el.nativeElement, &#x27;backgroundColor&#x27;, &#x27;yellow&#x27;);\n  }\n}</code></pre></div>","hand":true},{"id":"angular-f0150","card":"q-angular-029-elementref-vs-renderer2","sec":"angular-s030","q":"Which variant of the highlight directive is the unsafe one?","a":"<p>The direct-style one: <code>this.el.nativeElement.style.backgroundColor = 'yellow'</code>.</p>","hand":true},{"id":"angular-f0151","card":"q-angular-029-elementref-vs-renderer2","sec":"angular-s030","q":"How do you test a directive that injects <code>ElementRef</code>?","a":"<p>Mock <code>ElementRef</code> with a spy and inject the directive through <code>TestBed</code>:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>beforeEach(() =&gt; {\n  TestBed.configureTestingModule({\n    providers: [\n      OnlineStatusDirective,\n      { provide: ElementRef&lt;HTMLAnchorElement&gt;, useValue: jasmine.createSpy(&#x27;ElementRefSpy&#x27;) }\n    ]\n  });\n  directive = TestBed.inject(OnlineStatusDirective);\n});\n\nit(&#x27;should create an instance&#x27;, () =&gt; {\n  expect(directive).toBeTruthy();\n});</code></pre></div>","hand":true},{"id":"angular-f0152","card":"q-angular-030-tsconfig-json-project-root","sec":"angular-s031","q":"What does <code>tsconfig.json</code> do in an Angular project?","a":"<p>It tells TypeScript how to compile. <code>compilerOptions</code> are TypeScript settings. <code>angularCompilerOptions</code> are Angular-specific.</p>","hand":true},{"id":"angular-f0153","card":"q-angular-030-tsconfig-json-project-root","sec":"angular-s031","q":"Which <code>compilerOptions</code> setting is required for Angular decorators?","a":"<p><code>experimentalDecorators</code>.</p>","hand":true},{"id":"angular-f0154","card":"q-angular-030-tsconfig-json-project-root","sec":"angular-s031","q":"What are <code>tsconfig.app.json</code> and <code>tsconfig.spec.json</code>?","a":"<p>Extra files that split concerns. <code>tsconfig.app.json</code> is for the app build and <code>tsconfig.spec.json</code> is for unit tests.</p>","hand":true},{"id":"angular-f0155","card":"q-angular-030-tsconfig-json-project-root","sec":"angular-s031","q":"What does a typical Angular <code>tsconfig.json</code> contain?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JSON</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>{\n  &quot;compileOnSave&quot;: false,\n  &quot;compilerOptions&quot;: {\n    &quot;baseUrl&quot;: &quot;./&quot;,\n    &quot;outDir&quot;: &quot;./dist/out-tsc&quot;,\n    &quot;strict&quot;: true,\n    &quot;experimentalDecorators&quot;: true,\n    &quot;target&quot;: &quot;ES2022&quot;,\n    &quot;module&quot;: &quot;ES2022&quot;,\n    &quot;lib&quot;: [&quot;ES2022&quot;, &quot;dom&quot;]\n  },\n  &quot;angularCompilerOptions&quot;: {\n    &quot;strictInjectionParameters&quot;: true,\n    &quot;strictInputAccessModifiers&quot;: true,\n    &quot;strictTemplates&quot;: true\n  }</code></pre></div>","hand":true},{"id":"angular-f0156","card":"q-angular-031-environments","sec":"angular-s032","q":"What are Angular environment files for?","a":"<p>They change values (API URLs, keys, feature flags, footers) per build target without <code>if</code> logic. All files must have the same properties and types.</p>","hand":true},{"id":"angular-f0157","card":"q-angular-031-environments","sec":"angular-s032","q":"What is the file layout for environments?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Text</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>src/environments/\n├── environment.ts              # production\n└── environment.development.ts  # development</code></pre></div>","hand":true},{"id":"angular-f0158","card":"q-angular-031-environments","sec":"angular-s032","q":"What do the production and development environment files contain in the course app?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>// environment.ts\nexport const environment = { appFooter: &#x27;© Gem Finder, LLC&#x27; };\n\n// environment.development.ts\nexport const environment = { appFooter: &#x27;© Gem Finder, LLC ~ Development Build&#x27; };</code></pre></div>","hand":true},{"id":"angular-f0159","card":"q-angular-031-environments","sec":"angular-s032","q":"Which environment file should you always import, and how does the CLI pick the right one?","a":"<p>Always import from the production file (<code>environment.ts</code>). At build time the CLI replaces that import with the file for the active target.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>import { environment } from &#x27;src/environments/environment&#x27;;</code></pre></div>","hand":true},{"id":"angular-f0160","card":"q-angular-031-environments","sec":"angular-s032","q":"How do you use an environment value in a component?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>export class AppComponent {\n  public appFooter = environment.appFooter;\n  constructor(public messageService: MessageService) { }\n}</code></pre></div>","hand":true},{"id":"angular-f0161","card":"q-angular-031-environments","sec":"angular-s032","q":"Which commands build with the development and production environment?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>npm start                                # = ng serve, uses environment.development.ts\nnpm run start:production                 # = ng serve --configuration production, uses environment.ts\nng build --configuration production</code></pre></div>","hand":true},{"id":"angular-f0162","card":"q-angular-031-environments","sec":"angular-s032","q":"How does the environment import get replaced in development and production builds?","a":"<p>Development builds swap the import to <code>src/environments/environment.development</code>. Production builds keep <code>src/environments/environment</code>.</p>","hand":true},{"id":"angular-f0163","card":"q-angular-031-environments","sec":"angular-s032","q":"What typical contents do environment files hold?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>// environment.ts / environment.development.ts\nexport const environment = { production: true,  apiUrl: &#x27;https://api.production.com&#x27; };\nexport const environment = { production: false, apiUrl: &#x27;http://localhost:3000&#x27; };</code></pre></div>","hand":true},{"id":"angular-f0164","card":"q-angular-031-environments","sec":"angular-s032","q":"How can environment config be nested?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>export const environment = {\n  api: { baseUrl: &#x27;https://api.example.com&#x27;, timeout: 5000, retries: 3 },\n  features: { darkMode: true, notifications: false },\n  keys: { googleMaps: &#x27;YOUR_KEY_HERE&#x27; }\n};</code></pre></div>","hand":true},{"id":"angular-f0165","card":"q-angular-031-environments","sec":"angular-s032","q":"What are feature flags in environment files?","a":"<p>Plain key-value entries such as <code>enableAnalytics</code>, <code>enableDebugMode</code> and <code>maxRetries</code>.</p>","hand":true},{"id":"angular-f0166","card":"q-angular-032-11-dependency-injection","sec":"angular-s033","q":"What is dependency injection (DI)?","a":"<p>A design pattern where a class <strong>requests</strong> dependencies from an external source instead of creating them. Angular cannot be used without it.</p>","hand":true},{"id":"angular-f0167","card":"q-angular-033-how-it-works","sec":"angular-s034","q":"What is an injector and a token in Angular DI?","a":"<p>The injector is a collection of key-value pairs. Each key is a unique <strong>token</strong>.</p>","hand":true},{"id":"angular-f0168","card":"q-angular-033-how-it-works","sec":"angular-s034","q":"How does Angular resolve <code>constructor(private api: ApiService)</code>?","a":"<p>The type annotation is the token. Angular looks it up in the injector and injects the instance.</p>","hand":true},{"id":"angular-f0169","card":"q-angular-033-how-it-works","sec":"angular-s034","q":"What can be injected in Angular?","a":"<p>Services (most common), strings, booleans, object literals, anything with a provider.</p>","hand":true},{"id":"angular-f0170","card":"q-angular-034-constructor-injection-syntax","sec":"angular-s035","q":"What is the difference between constructor parameters with and without an access modifier?","a":"<p>With a modifier it is shorthand that declares and assigns a property. Without one, the parameters are plain with no class property.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>constructor(private api: ApiService, private route: ActivatedRoute) { }   // shorthand: declares and assigns a property\nconstructor(api: ApiService, route: ActivatedRoute) { }                    // no modifier: plain parameters, no class property</code></pre></div>","hand":true},{"id":"angular-f0171","card":"q-angular-034-constructor-injection-syntax","sec":"angular-s035","q":"When do you use <code>private</code>, <code>public</code> and <code>protected</code> on an injected constructor parameter?","a":"<p><code>private</code> is recommended for internal use. <code>public</code> is needed in the template, e.g. <code>{{ messageService.count() }}</code>. <code>protected</code> is for subclasses.</p>","hand":true},{"id":"angular-f0172","card":"q-angular-035-declaring-dependencies-injectable-and-pr","sec":"angular-s036","q":"What do the <code>providedIn</code> values <code>'root'</code>, <code>null</code> and <code>'platform'</code> mean?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Value</th><th>Behavior</th></tr></thead>\n    <tbody>\n      <tr><td><code>'root'</code> (recommended, CLI default)</td><td>one app-wide singleton. No providers entry needed</td></tr>\n      <tr><td><code>null</code> / bare <code>@Injectable()</code></td><td>must be added to a module or component <code>providers</code> array. More control over scope</td></tr>\n      <tr><td><code>'platform'</code></td><td>one instance shared across all Angular apps in the project. Rare</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"angular-f0173","card":"q-angular-035-declaring-dependencies-injectable-and-pr","sec":"angular-s036","q":"How do you write an injectable that needs no provider, and one that must be provided?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@Injectable({ providedIn: &#x27;root&#x27; })     // inject directly, no provider needed\nexport class ApiService { }\n\n@Injectable()                            // must be provided\nexport class CustomService { }</code></pre></div>","hand":true},{"id":"angular-f0174","card":"q-angular-036-providing-dependencies","sec":"angular-s037","q":"How do you provide a service in a module and in a standalone component?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>// module\n@NgModule({ providers: [CustomService] })\nexport class AppModule { }\n\n// standalone component (new instance scoped to this component)\n@Component({ standalone: true, providers: [CustomService] })\nexport class ExampleComponent {\n  constructor(private custom: CustomService) { }\n}</code></pre></div>","hand":true},{"id":"angular-f0175","card":"q-angular-036-providing-dependencies","sec":"angular-s037","q":"When does <code>providers: []</code> stay empty in <code>AppModule</code>?","a":"<p>When every service uses <code>providedIn: 'root'</code>.</p>","hand":true},{"id":"angular-f0176","card":"q-angular-036-providing-dependencies","sec":"angular-s037","q":"What is the long form of the shorthand <code>providers: [ApiService]</code>?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>{ provide: ApiService, useClass: ApiService }</code></pre></div>","hand":true},{"id":"angular-f0177","card":"q-angular-036-providing-dependencies","sec":"angular-s037","q":"What does <code>provide</code> hold in a provider object?","a":"<p>The unique token: a class, a string like <code>'API_URL'</code>, or an <code>InjectionToken</code>. The second key says what to inject.</p>","hand":true},{"id":"angular-f0178","card":"q-angular-036-providing-dependencies","sec":"angular-s037","q":"What does <code>useClass</code> do in a provider?","a":"<p>It swaps the implementation:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>{ provide: ApiService, useClass: MockApiService }</code></pre></div>","hand":true},{"id":"angular-f0179","card":"q-angular-036-providing-dependencies","sec":"angular-s037","q":"What does <code>useValue</code> do in a provider?","a":"<p>It provides strings, booleans, object literals and config:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>{ provide: &#x27;API_URL&#x27;, useValue: &#x27;https://api.example.com&#x27; }\n{ provide: &#x27;DEBUG_MODE&#x27;, useValue: true }\n{ provide: &#x27;CONFIG&#x27;, useValue: { apiUrl: &#x27;https://api.example.com&#x27;, timeout: 5000 } }</code></pre></div>","hand":true},{"id":"angular-f0180","card":"q-angular-036-providing-dependencies","sec":"angular-s037","q":"What does <code>useFactory</code> do in a provider, and what is <code>deps</code> for?","a":"<p>It provides a computed value, optionally with dependencies listed in <code>deps</code>:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>{ provide: &#x27;LOGGER&#x27;, useFactory: () =&gt; console.log.bind(console) }\n{\n  provide: &#x27;API_CLIENT&#x27;,\n  useFactory: (http: HttpClient) =&gt; new ApiClient(http),\n  deps: [HttpClient]\n}</code></pre></div>","hand":true},{"id":"angular-f0181","card":"q-angular-036-providing-dependencies","sec":"angular-s037","q":"What does <code>useExisting</code> do in a provider?","a":"<p>It aliases one token to another (e.g. for backwards compatibility):</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>{ provide: &#x27;LoggerAlias&#x27;, useExisting: LoggerService }</code></pre></div>","hand":true},{"id":"angular-f0182","card":"q-angular-036-providing-dependencies","sec":"angular-s037","q":"How do you provide and inject a value with a string token?","a":"<p>Define the token, provide it with <code>useValue</code>, and inject it with <code>@Inject</code>:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>export const API_URL = &#x27;API_URL&#x27;;\n\n@NgModule({ providers: [{ provide: API_URL, useValue: &#x27;https://api.example.com&#x27; }] })\n\nconstructor(@Inject(API_URL) private apiUrl: string) { }</code></pre></div>","hand":true},{"id":"angular-f0183","card":"q-angular-036-providing-dependencies","sec":"angular-s037","q":"What is <code>InjectionToken</code> and how do you use it?","a":"<p>It is a type-safe token, preferred over strings:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>export const API_CONFIG = new InjectionToken&lt;ApiConfig&gt;(&#x27;api.config&#x27;);\n\n@NgModule({\n  providers: [{ provide: API_CONFIG, useValue: { url: &#x27;https://api.example.com&#x27;, timeout: 5000 } }]\n})\n\nconstructor(@Inject(API_CONFIG) private config: ApiConfig) { }</code></pre></div>","hand":true},{"id":"angular-f0184","card":"q-angular-036-providing-dependencies","sec":"angular-s037","q":"How do you choose a provider by environment with a factory function?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>export function loggerFactory() {\n  return environment.production ? productionLogger : devLogger;\n}\n\n@NgModule({ providers: [{ provide: &#x27;LOGGER&#x27;, useFactory: loggerFactory }] })</code></pre></div>","hand":true},{"id":"angular-f0185","card":"q-angular-036-providing-dependencies","sec":"angular-s037","q":"Do standalone and module apps provide dependencies differently?","a":"<p>They use the same patterns. Only the location of <code>providers</code> differs.</p>","hand":true},{"id":"angular-f0186","card":"q-angular-037-change-detection","sec":"angular-s038","q":"What is change detection in Angular, and which two strategies exist?","a":"<p>It is how Angular checks application state and updates the UI. The strategies are <code>Default</code> and <code>OnPush</code>, set through <code>changeDetection</code>.</p>","hand":true},{"id":"angular-f0187","card":"q-angular-037-change-detection","sec":"angular-s038","q":"What does the <code>Default</code> change detection strategy do?","a":"<p>It runs on data mutation inside objects and arrays, property redefinition, and events (API calls, click handlers). It starts at the root component, compares the new state tree to the old with strict equality, and reruns only what changed. It works everywhere, but checks all components, so it is slower with many components.</p>","hand":true},{"id":"angular-f0188","card":"q-angular-037-change-detection","sec":"angular-s038","q":"What does the <code>OnPush</code> strategy do and what does it require?","a":"<p>It skips the component and its sub-tree unless a property is <strong>redefined</strong>, an <strong>event</strong> fires, or change detection is called <strong>manually</strong>. It is faster, but requires immutable data (never mutate in place).</p>","hand":true},{"id":"angular-f0189","card":"q-angular-037-change-detection","sec":"angular-s038","q":"When should you use <code>OnPush</code>?","a":"<p>For components with many children, immutable data, and where performance matters.</p>","hand":true},{"id":"angular-f0190","card":"q-angular-037-change-detection","sec":"angular-s038","q":"How do you enable <code>OnPush</code> on a component?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@Component({\n  selector: &#x27;app-high-scores&#x27;,\n  changeDetection: ChangeDetectionStrategy.OnPush\n})</code></pre></div>","hand":true},{"id":"angular-f0191","card":"q-angular-037-change-detection","sec":"angular-s038","q":"Why is <code>HighScoresComponent</code> a working <code>OnPush</code> example?","a":"<p><code>players$</code> is declared once, set once in <code>ngOnInit</code>, and never mutated.</p>","hand":true},{"id":"angular-f0192","card":"q-angular-037-change-detection","sec":"angular-s038","q":"What is the best pairing with <code>OnPush</code>, and why?","a":"<p>The <code>async</code> pipe. The observable emits a new reference and the async pipe triggers detection, so no manual change detection is needed.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">HTML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>&lt;div *ngIf=&quot;data$ | async as data&quot;&gt;\n  &lt;div *ngFor=&quot;let item of data&quot;&gt;{{ item.name }}&lt;/div&gt;\n&lt;/div&gt;</code></pre></div>","hand":true},{"id":"angular-f0193","card":"q-angular-038-lifecycle-hooks","sec":"angular-s039","q":"What are lifecycle hooks and how do you use them?","a":"<p>They run code at specific moments of a component or directive lifecycle. Implement the matching interface from <code>@angular/core</code> (autocomplete, type safety, compile checks; optional but recommended) and add the public method.</p>","hand":true},{"id":"angular-f0194","card":"q-angular-038-lifecycle-hooks","sec":"angular-s039","q":"What are the Angular lifecycle hooks and when does each run?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Hook</th><th>When</th></tr></thead>\n    <tbody>\n      <tr><td><code>ngOnChanges</code></td><td>input properties change</td></tr>\n      <tr><td><code>ngOnInit</code></td><td>once, after construction, with injected dependencies and inputs available</td></tr>\n      <tr><td><code>ngDoCheck</code></td><td>every change detection run</td></tr>\n      <tr><td><code>ngAfterContentInit</code></td><td>after projected content is initialized</td></tr>\n      <tr><td><code>ngAfterContentChecked</code></td><td>after content is checked</td></tr>\n      <tr><td><code>ngAfterViewInit</code></td><td>after the view is initialized</td></tr>\n      <tr><td><code>ngAfterViewChecked</code></td><td>after the view is checked</td></tr>\n      <tr><td><code>ngOnDestroy</code></td><td>just before destruction</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"angular-f0195","card":"q-angular-038-lifecycle-hooks","sec":"angular-s039","q":"In what order do lifecycle hooks run on creation?","a":"<p>Constructor, <code>ngOnChanges</code> (if inputs), <code>ngOnInit</code>, <code>ngDoCheck</code>, <code>ngAfterContentInit</code>, <code>ngAfterContentChecked</code>, <code>ngAfterViewInit</code>, <code>ngAfterViewChecked</code>.</p>","hand":true},{"id":"angular-f0196","card":"q-angular-038-lifecycle-hooks","sec":"angular-s039","q":"Which hooks run on updates and at the end of the lifecycle?","a":"<p>On updates: <code>ngOnChanges</code>, <code>ngDoCheck</code>, <code>ngAfterContentChecked</code>, <code>ngAfterViewChecked</code>. Finally <code>ngOnDestroy</code>.</p>","hand":true},{"id":"angular-f0197","card":"q-angular-038-lifecycle-hooks","sec":"angular-s039","q":"What is <code>ngOnInit</code> for, and why prefer it over the constructor?","a":"<p>It is the most common hook, for initialization and API calls. The constructor should only inject dependencies and do trivial assignments, because <code>ngOnInit</code> is guaranteed access to the injector and inputs.</p>","hand":true},{"id":"angular-f0198","card":"q-angular-038-lifecycle-hooks","sec":"angular-s039","q":"What is <code>ngOnDestroy</code> for, and how do you write it?","a":"<p>It is the second most common hook, used to clean up by unsubscribing, stopping timers and unregistering callbacks:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>export class ExampleComponent implements OnInit, OnDestroy {\n  private subscription: Subscription;\n\n  public ngOnInit(): void {\n    this.subscription = this.api.getData$().subscribe();\n  }\n\n  public ngOnDestroy(): void {\n    this.subscription.unsubscribe();\n  }\n}</code></pre></div>","hand":true},{"id":"angular-f0199","card":"q-angular-038-lifecycle-hooks","sec":"angular-s039","q":"How do you implement several lifecycle hooks in one class?","a":"<p>List the interfaces, then add each method: <code>implements OnInit, OnDestroy, AfterViewInit</code>.</p>","hand":true},{"id":"angular-f0200","card":"q-angular-038-lifecycle-hooks","sec":"angular-s039","q":"How do you react to input changes with <code>ngOnChanges</code>?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>public ngOnChanges(changes: SimpleChanges): void {     // react to input changes\n  if (changes[&#x27;inputProperty&#x27;]) {\n    this.handleChange();\n  }\n}</code></pre></div>","hand":true},{"id":"angular-f0201","card":"q-angular-038-lifecycle-hooks","sec":"angular-s039","q":"What is <code>ngAfterViewInit</code> used for?","a":"<p>View children and DOM work.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>public ngAfterViewInit(): void {                       // view children, DOM work\n}</code></pre></div>","hand":true},{"id":"angular-f0202","card":"q-angular-039-13-routing-and-navigation","sec":"angular-s040","q":"What is the Angular Router and what are its two parts?","a":"<p>An optional package. Part one is to <strong>define routes</strong> and bootstrap the router. Part two is to <strong>use routes</strong> in templates.</p>","hand":true},{"id":"angular-f0203","card":"q-angular-039-13-routing-and-navigation","sec":"angular-s040","q":"Why does route order matter in Angular?","a":"<p>Angular uses the first matching route. Put specific routes first, the empty-path redirect after them, and the <code>**</code> catch-all (404 handling) last.</p>","hand":true},{"id":"angular-f0204","card":"q-angular-040-defining-routes","sec":"angular-s041","q":"What does a full routes array look like, with lazy loading, titles, preload data and redirects?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const routes: Routes = [\n  {\n    path: &#x27;profile/:id&#x27;,\n    loadComponent: () =&gt; import(&#x27;./pages/profile/profile.component&#x27;).then(m =&gt; m.ProfileComponent),\n    title: (route: ActivatedRouteSnapshot) =&gt; `Gem Finder | Profile for ${route.paramMap.get(&#x27;id&#x27;)}`\n  },\n  {\n    path: &#x27;players&#x27;,\n    loadChildren: () =&gt; import(&#x27;./pages/players/players.module&#x27;).then(m =&gt; m.PlayersModule),\n    title: &#x27;Gem Finder | All Players&#x27;,\n    data: { preload: true }\n  },\n  {\n    path: &#x27;leaderboards&#x27;,\n    loadChildren: () =&gt; import(&#x27;./pages/leaderboards/leaderboards.module&#x27;).then(m =&gt; m.LeaderboardsModule),\n    title: &#x27;Gem Finder | Leaderboards&#x27;\n  },\n  {\n    path: &#x27;messages&#x27;,\n    loadComponent: () =&gt; import(&#x27;./pages/messages/messages.component&#x27;).then(m =&gt; m.MessagesComponent),\n    data: { preload: true }\n  },\n  { path: &#x27;&#x27;, redirectTo: `/players`, pathMatch: &#x27;full&#x27; },\n  { path: &#x27;**&#x27;, redirectTo: &#x27;/players&#x27; }\n];</code></pre></div>","hand":true},{"id":"angular-f0205","card":"q-angular-040-defining-routes","sec":"angular-s041","q":"How is the routes array registered in the routing module with a custom preloading strategy?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@NgModule({\n  imports: [RouterModule.forRoot(routes, { preloadingStrategy: PreloadingService })],\n  exports: [RouterModule]\n})\nexport class AppRoutingModule { }</code></pre></div>","hand":true},{"id":"angular-f0206","card":"q-angular-041-route-properties","sec":"angular-s042","q":"What do <code>path</code> values <code>''</code>, <code>**</code> and <code>:id</code> mean?","a":"<p><code>path</code> is the URL segment, relative to the parent route or base href. <code>''</code> is the root, <code>**</code> is a wildcard, and <code>:id</code> is a dynamic parameter.</p>","hand":true},{"id":"angular-f0207","card":"q-angular-041-route-properties","sec":"angular-s042","q":"What is the difference between <code>redirectTo: '/players'</code> and <code>redirectTo: 'players'</code>?","a":"<p><code>/players</code> is absolute (from base href). <code>players</code> is relative to the parent.</p>","hand":true},{"id":"angular-f0208","card":"q-angular-041-route-properties","sec":"angular-s042","q":"What does <code>pathMatch</code> do and why does <code>path: ''</code> need <code>'full'</code>?","a":"<p><code>'prefix'</code> (default) matches partially, <code>'full'</code> requires an exact match. <code>path: ''</code> needs <code>'full'</code> because the empty path prefixes every URL.</p>","hand":true},{"id":"angular-f0209","card":"q-angular-041-route-properties","sec":"angular-s042","q":"<code>loadChildren</code> vs <code>loadComponent</code>?","a":"<p><code>loadChildren</code> lazy-loads a <strong>module</strong>. <code>loadComponent</code> lazy-loads a <strong>standalone component</strong>.</p>","hand":true},{"id":"angular-f0210","card":"q-angular-041-route-properties","sec":"angular-s042","q":"What can the route <code>title</code> property be?","a":"<p>A static string, or a function receiving <code>ActivatedRouteSnapshot</code> (it can use route params and DI). It sets the tab and bookmark name.</p>","hand":true},{"id":"angular-f0211","card":"q-angular-041-route-properties","sec":"angular-s042","q":"What is the route <code>data</code> property for?","a":"<p>Custom key-value metadata: preload flags, roles, animation state.</p>","hand":true},{"id":"angular-f0212","card":"q-angular-041-route-properties","sec":"angular-s042","q":"What is the base href and where is it set?","a":"<p>It is the root URL that routes are relative to. It is set in <code>index.html</code>:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">HTML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>&lt;head&gt;\n  &lt;base href=&quot;/&quot;&gt;\n&lt;/head&gt;\n&lt;body&gt;\n  &lt;app-root&gt;&lt;/app-root&gt;\n&lt;/body&gt;</code></pre></div>","hand":true},{"id":"angular-f0213","card":"q-angular-041-route-properties","sec":"angular-s042","q":"What does <code>RouterModule.forRoot(routes, options?)</code> do, and what options does it take?","a":"<p>It is the main route definition, called <strong>once</strong>. The optional second argument takes <code>preloadingStrategy</code>, <code>enableTracing</code> (debug) and <code>useHash</code> (hash-based URLs). <code>exports: [RouterModule]</code> makes router directives available app-wide.</p>","hand":true},{"id":"angular-f0214","card":"q-angular-041-route-properties","sec":"angular-s042","q":"What does <code>RouterModule.forChild(routes)</code> do?","a":"<p>It defines a feature module's own routes. The empty <code>path: ''</code> is relative to the lazy parent path:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const routes: Routes = [{ path: &#x27;&#x27;, component: PlayersComponent }];\n\n@NgModule({\n  imports: [RouterModule.forChild(routes)],\n  exports: [RouterModule]\n})\nexport class PlayersRoutingModule { }</code></pre></div>","hand":true},{"id":"angular-f0215","card":"q-angular-042-lazy-loading","sec":"angular-s043","q":"What is lazy loading in Angular routing?","a":"<p>Loading modules or components only when a route is first visited. It is Angular's default for routes (<code>loadChildren</code> / <code>loadComponent</code>).</p>","hand":true},{"id":"angular-f0216","card":"q-angular-042-lazy-loading","sec":"angular-s043","q":"What is the dynamic import syntax for lazy loading?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>() =&gt; import(&#x27;./path/to/module&#x27;).then(m =&gt; m.ModuleName)</code></pre></div>\n<p>The arrow function returns a Promise, <code>import()</code> loads an ES module asynchronously, and <code>.then</code> extracts the exported class.</p>","hand":true},{"id":"angular-f0217","card":"q-angular-042-lazy-loading","sec":"angular-s043","q":"What are the upside and downside of lazy loading?","a":"<p>Upside: faster first load and a smaller initial bundle. Downside: network lag on first navigation to a page, noticeable on slow connections.</p>","hand":true},{"id":"angular-f0218","card":"q-angular-043-preloading-strategies","sec":"angular-s044","q":"What does preloading do?","a":"<p>It loads lazy modules in the background after the initial page load, giving fast startup and low navigation lag. Set it through <code>preloadingStrategy</code>.</p>","hand":true},{"id":"angular-f0219","card":"q-angular-043-preloading-strategies","sec":"angular-s044","q":"What do <code>NoPreloading</code> and <code>PreloadAllModules</code> do?","a":"<p><code>NoPreloading</code> (default) loads everything lazily on demand. <code>PreloadAllModules</code> loads everything on launch. It is fine for small apps, but launch is slow with many modules.</p>","hand":true},{"id":"angular-f0220","card":"q-angular-043-preloading-strategies","sec":"angular-s044","q":"How do you set a built-in preloading strategy?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>import { NoPreloading, PreloadAllModules } from &#x27;@angular/router&#x27;;\nRouterModule.forRoot(routes, { preloadingStrategy: PreloadAllModules })   // or NoPreloading</code></pre></div>","hand":true},{"id":"angular-f0221","card":"q-angular-043-preloading-strategies","sec":"angular-s044","q":"How do you write a custom preloading strategy?","a":"<p>Write a class implementing <code>PreloadingStrategy</code> with a public <code>preload(route, fn)</code> method returning an Observable. Call <code>fn()</code> to preload, return <code>of(null)</code> to skip.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@Injectable({ providedIn: &#x27;root&#x27; })\nexport class PreloadingService implements PreloadingStrategy {\n  public preload(route: Route, fn: () =&gt; Observable&lt;any&gt;): Observable&lt;any&gt; {\n    return (route.data &amp;&amp; route.data[&#x27;preload&#x27;]) ? fn() : of(null);\n  }\n}</code></pre></div>","hand":true},{"id":"angular-f0222","card":"q-angular-043-preloading-strategies","sec":"angular-s044","q":"Why is <code>route.data['preload']</code> written with brackets?","a":"<p>Bracket access is required by Angular's type definition. Mark routes with <code>data: { preload: true }</code>.</p>","hand":true},{"id":"angular-f0223","card":"q-angular-043-preloading-strategies","sec":"angular-s044","q":"What does the network show with the custom preload setup?","a":"<p>The first load fetches <code>main.js</code> and the current page module (<code>players</code>), and preloads <code>messages</code> in the background. <code>leaderboards</code> has no flag, so it is fetched only when visited. Navigating to messages causes no request.</p>","hand":true},{"id":"angular-f0224","card":"q-angular-044-dynamic-route-parameters","sec":"angular-s045","q":"What does <code>path: 'profile/:id'</code> match, and can a route have several parameters?","a":"<p>It matches <code>/profile/123</code>, <code>/profile/abc</code> and so on. Multiple parameters are allowed:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>{ path: &#x27;users/:userId/posts/:postId&#x27;, component: PostComponent }     // /users/123/posts/456</code></pre></div>","hand":true},{"id":"angular-f0225","card":"q-angular-044-dynamic-route-parameters","sec":"angular-s045","q":"<code>ActivatedRouteSnapshot</code> vs <code>ActivatedRoute</code>?","a":"<p><code>ActivatedRouteSnapshot</code> is a synchronous snapshot of the route at one moment, used in route config such as the <code>title</code> function (<code>route.paramMap.get('id')</code>). <code>ActivatedRoute</code> is injected into components and exposes <strong>observables</strong> because values can change over time.</p>","hand":true},{"id":"angular-f0226","card":"q-angular-044-dynamic-route-parameters","sec":"angular-s045","q":"How does <code>ProfileComponent</code> read the <code>id</code> route parameter and load the player?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>constructor(\n  private api: ApiService,\n  private route: ActivatedRoute\n) { }\n\npublic ngOnInit(): void {\n  this.player$ = this.route.paramMap.pipe(\n    map(params =&gt; params.get(&#x27;id&#x27;) ?? &#x27;&#x27;),\n    switchMap(id =&gt; this.api.getPlayerById$(id))\n  );\n}</code></pre></div>","hand":true},{"id":"angular-f0227","card":"q-angular-044-dynamic-route-parameters","sec":"angular-s045","q":"Why use <code>switchMap</code> when reading route parameters?","a":"<p>It swaps to the new inner request whenever the parameter changes.</p>","hand":true},{"id":"angular-f0228","card":"q-angular-044-dynamic-route-parameters","sec":"angular-s045","q":"What methods does <code>ParamMap</code> offer?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>route.paramMap.get(&#x27;id&#x27;);            // single value\nroute.paramMap.getAll(&#x27;tag&#x27;);        // multiple values\nroute.paramMap.has(&#x27;id&#x27;);            // existence check\nroute.paramMap.keys;                 // all parameter names</code></pre></div>","hand":true},{"id":"angular-f0229","card":"q-angular-044-dynamic-route-parameters","sec":"angular-s045","q":"How do you read route params, query params, fragment and route data from <code>ActivatedRoute</code>?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>this.route.paramMap.pipe(map(params =&gt; params.get(&#x27;id&#x27;)))             // route params\nthis.route.queryParamMap.pipe(map(params =&gt; params.get(&#x27;search&#x27;)))    // ?search=value\nthis.route.fragment.pipe(map(fragment =&gt; fragment))                   // #section\nthis.route.data.pipe(map(data =&gt; data[&#x27;customKey&#x27;]))                  // route data</code></pre></div>","hand":true},{"id":"angular-f0230","card":"q-angular-044-dynamic-route-parameters","sec":"angular-s045","q":"For the URL <code>/profile/123#contact</code>, what do <code>paramMap.get('id')</code> and <code>fragment</code> return?","a":"<p><code>paramMap.get('id')</code> returns <code>'123'</code> (route <code>profile/:id</code>) and <code>fragment</code> returns <code>'contact'</code>.</p>","hand":true},{"id":"angular-f0231","card":"q-angular-044-dynamic-route-parameters","sec":"angular-s045","q":"For <code>/players?search=john</code> and <code>/users/123/posts/456</code>, what do <code>queryParamMap.get('search')</code> and <code>get('userId')</code> / <code>get('postId')</code> return?","a":"<p><code>queryParamMap.get('search')</code> returns <code>'john'</code>. For route <code>users/:userId/posts/:postId</code>, <code>get('userId')</code> returns <code>'123'</code> and <code>get('postId')</code> returns <code>'456'</code>.</p>","hand":true},{"id":"angular-f0232","card":"q-angular-045-router-in-templates","sec":"angular-s046","q":"What is <code>&lt;router-outlet&gt;</code>?","a":"<p>A built-in component that anchors where route content renders. The routed component is inserted as a sibling right after it.</p>","hand":true},{"id":"angular-f0233","card":"q-angular-045-router-in-templates","sec":"angular-s046","q":"What do <code>routerLink</code> and <code>routerLinkActive=\"cls\"</code> do?","a":"<p><code>routerLink</code> replaces <code>href</code> for internal navigation. <code>routerLinkActive=\"cls\"</code> adds a CSS class while the link's route is active.</p>","hand":true},{"id":"angular-f0234","card":"q-angular-045-router-in-templates","sec":"angular-s046","q":"What does the app shell template with nav links, <code>router-outlet</code> and footer look like?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">HTML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>&lt;nav class=&quot;nav nav-pills nav-fill&quot;&gt;\n  &lt;a class=&quot;nav-link&quot; routerLink=&quot;players&quot; routerLinkActive=&quot;active&quot;&gt;\n    &lt;i class=&quot;bi bi-people-fill&quot;&gt;&lt;/i&gt;\n  &lt;/a&gt;\n  &lt;a class=&quot;nav-link&quot; routerLink=&quot;leaderboards&quot; routerLinkActive=&quot;active&quot;&gt;\n    &lt;i class=&quot;bi bi-trophy-fill&quot;&gt;&lt;/i&gt;\n  &lt;/a&gt;\n  &lt;a class=&quot;nav-link position-relative&quot; routerLink=&quot;messages&quot; routerLinkActive=&quot;active&quot;&gt;\n    &lt;i class=&quot;bi bi-inbox-fill&quot;&gt;&lt;/i&gt;\n    &lt;span *ngIf=&quot;messageService.count()&quot;&gt;&amp;nbsp;({{ messageService.count() }})&lt;/span&gt;\n  &lt;/a&gt;\n&lt;/nav&gt;\n\n&lt;router-outlet&gt;&lt;/router-outlet&gt;\n\n&lt;footer class=&quot;position-absolute bottom-0 start-0 w-100 my-3 text-center&quot;&gt;\n  &lt;small class=&quot;fs-6&quot;&gt;{{ appFooter }}&lt;/small&gt;\n&lt;/footer&gt;</code></pre></div>","hand":true},{"id":"angular-f0235","card":"q-angular-045-router-in-templates","sec":"angular-s046","q":"What are the forms of <code>routerLink</code> values, and which one is wrong?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">HTML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>&lt;a routerLink=&quot;players&quot;&gt;All Players&lt;/a&gt;                         &lt;!-- relative to current route --&gt;\n&lt;a routerLink=&quot;/players&quot;&gt;All Players&lt;/a&gt;                        &lt;!-- absolute, from base href --&gt;\n&lt;a [routerLink]=&quot;[&#x27;/profile&#x27;, player.id]&quot;&gt;{{ player.name }}&lt;/a&gt; &lt;!-- array: each item is a path segment --&gt;\n&lt;a routerLink=&quot;[&#x27;/profile&#x27;, player.id]&quot;&gt;Link&lt;/a&gt;                &lt;!-- WRONG: no brackets = literal string --&gt;</code></pre></div>","hand":true},{"id":"angular-f0236","card":"q-angular-045-router-in-templates","sec":"angular-s046","q":"Why are square brackets required on <code>[routerLink]</code> for dynamic values?","a":"<p>Without them the value is a literal string. <code>[routerLink]=\"['/profile', player.id]\"</code> yields <code>/profile/123</code>, <code>/profile/456</code> and so on.</p>","hand":true},{"id":"angular-f0237","card":"q-angular-045-router-in-templates","sec":"angular-s046","q":"What does <code>routerLinkActive</code> produce on the links, and how can you style it?","a":"<p>The active link gets the class, the others do not. Style it with:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">CSS</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>.nav-link { color: gray; }\n.nav-link.active { color: blue; font-weight: bold; }</code></pre></div>","hand":true},{"id":"angular-f0238","card":"q-angular-045-router-in-templates","sec":"angular-s046","q":"How do you define a lazy route with role and preload data, and a route with two parameters?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>{ path: &#x27;admin&#x27;, loadChildren: () =&gt; import(&#x27;./admin/admin.module&#x27;).then(m =&gt; m.AdminModule), data: { role: &#x27;admin&#x27;, preload: true } }\n{ path: &#x27;category/:categoryId/product/:productId&#x27;, component: ProductDetailComponent }</code></pre></div>","hand":true},{"id":"angular-f0239","card":"q-angular-046-signals-angular-16-developer-preview-at","sec":"angular-s047","q":"What are signals in Angular?","a":"<p>A reactive pattern where data is wrapped in getters and setters, so Angular tracks changes and updates only what changed instead of checking every component. The API may change, so check the docs.</p>","hand":true},{"id":"angular-f0240","card":"q-angular-046-signals-angular-16-developer-preview-at","sec":"angular-s047","q":"How do you create and read a signal?","a":"<p><code>signal(initialValue)</code> returns a <code>WritableSignal</code>. The type is inferred or given explicitly. <strong>Read a signal by calling it.</strong></p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const count = signal(0);                       // inferred number\npublic unread = signal&lt;Message[]&gt;([]);         // explicit type\nthis.unread();                                 // read value</code></pre></div>","hand":true},{"id":"angular-f0241","card":"q-angular-046-signals-angular-16-developer-preview-at","sec":"angular-s047","q":"<code>set</code>, <code>update</code> and <code>mutate</code> on a signal: how do they differ?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Method</th><th>Use</th></tr></thead>\n    <tbody>\n      <tr><td><code>set(value)</code></td><td>replace the value</td></tr>\n      <tr><td><code>update(fn)</code></td><td>return a new value from the current one (immutable, recommended)</td></tr>\n      <tr><td><code>mutate(fn)</code></td><td>change the current value in place (mutable, no return).</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"angular-f0242","card":"q-angular-046-signals-angular-16-developer-preview-at","sec":"angular-s047","q":"How do you set a signal from an HTTP response?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>this.http.get&lt;Message[]&gt;(&#x27;/assets/mocks/messages.json&#x27;)\n  .subscribe({ next: items =&gt; this.unread.set(items) });</code></pre></div>","hand":true},{"id":"angular-f0243","card":"q-angular-046-signals-angular-16-developer-preview-at","sec":"angular-s047","q":"How do you remove an item from a signal array immutably, and how in place?","a":"<p>Immutably with <code>update</code>, in place with <code>mutate</code>:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>this.unread.update(items =&gt; items.filter(item =&gt; item.id !== selected.id));\n\nthis.unread.mutate(items =&gt; {\n  const index = items.findIndex(item =&gt; item.id === selected.id);\n  items.splice(index, 1);\n});</code></pre></div>","hand":true},{"id":"angular-f0244","card":"q-angular-046-signals-angular-16-developer-preview-at","sec":"angular-s047","q":"What is <code>computed()</code> and what are its key properties?","a":"<p>It derives a <strong>read-only</strong> value from other signals. It is <strong>cached</strong> (recalculates only when dependencies change) and <strong>lazy</strong> (evaluated only when read), which suits filtering large arrays and heavy calculations.</p>","hand":true},{"id":"angular-f0245","card":"q-angular-046-signals-angular-16-developer-preview-at","sec":"angular-s047","q":"What happens if you call <code>set</code> on a computed signal?","a":"<p>It is an error, because <code>set</code> does not exist on a computed signal:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>public count = computed(() =&gt; this.unread().length);\n\ncount();            // read\ncount.set(5);       // error: set does not exist on a computed signal</code></pre></div>","hand":true},{"id":"angular-f0246","card":"q-angular-046-signals-angular-16-developer-preview-at","sec":"angular-s047","q":"How does a component use an <code>effect</code> in its constructor to set the page title from a signal?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>constructor(\n  private title: Title,\n  public messageService: MessageService\n) {\n  effect(() =&gt; {\n    this.title.setTitle(`Gem Finder | Messages (${this.messageService.count()})`);\n  });\n}</code></pre></div>","hand":true},{"id":"angular-f0247","card":"q-angular-046-signals-angular-16-developer-preview-at","sec":"angular-s047","q":"How do you show a signal value in a template?","a":"<p>Call it in the template:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">HTML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>&lt;span *ngIf=&quot;messageService.count()&quot;&gt;&amp;nbsp;({{ messageService.count() }})&lt;/span&gt;</code></pre></div>","hand":true},{"id":"angular-f0248","card":"q-angular-047-signals-angular-16-developer-preview-at","sec":"angular-s047","q":"How do you derive state with <code>computed</code> from a list signal?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>public items = signal&lt;Item[]&gt;([]);\npublic activeItems = computed(() =&gt; this.items().filter(item =&gt; item.active));\npublic hasItems = computed(() =&gt; this.items().length &gt; 0);</code></pre></div>","hand":true},{"id":"angular-f0249","card":"q-angular-047-signals-angular-16-developer-preview-at","sec":"angular-s047","q":"How do you add and remove items in a signal list?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>public addItem(item: Item)  { this.items.update(items =&gt; [...items, item]); }\npublic removeItem(id: string) { this.items.update(items =&gt; items.filter(item =&gt; item.id !== id)); }</code></pre></div>","hand":true},{"id":"angular-f0250","card":"q-angular-047-signals-angular-16-developer-preview-at","sec":"angular-s047","q":"How do you filter a list by a search signal with <code>computed</code>?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>public searchTerm = signal(&#x27;&#x27;);\npublic filteredItems = computed(() =&gt; {\n  const term = this.searchTerm().toLowerCase();\n  return this.items().filter(item =&gt; item.name.toLowerCase().includes(term));\n});</code></pre></div>","hand":true},{"id":"angular-f0251","card":"q-angular-047-signals-angular-16-developer-preview-at","sec":"angular-s047","q":"How do you model form-like state with signals?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>public username = signal(&#x27;&#x27;);\npublic email = signal(&#x27;&#x27;);\npublic isValid = computed(() =&gt; this.username().length &gt; 0 &amp;&amp; this.email().includes(&#x27;@&#x27;));</code></pre></div>","hand":true},{"id":"angular-f0252","card":"q-angular-047-signals-angular-16-developer-preview-at","sec":"angular-s047","q":"How do you write a counter with a signal?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>public count = signal(0);\npublic increment() { this.count.update(n =&gt; n + 1); }</code></pre></div>","hand":true},{"id":"angular-f0253","card":"q-angular-047-signals-angular-16-developer-preview-at","sec":"angular-s047","q":"What shape do <code>total</code> and <code>average</code> computed signals follow?","a":"<p>The same <code>computed(() =&gt; this.items().reduce(...))</code> shape.</p>","hand":true},{"id":"angular-f0254","card":"q-angular-047-signals-angular-16-developer-preview-at","sec":"angular-s047","q":"Signals vs observables: how do they differ?","a":"<p>Signals are synchronous, always hold a current value, have a simpler API and suit local state. Observables are asynchronous streams over time with a rich operator set and suit async work.</p>","hand":true},{"id":"angular-f0255","card":"q-angular-047-signals-angular-16-developer-preview-at","sec":"angular-s047","q":"How do you set and read a signal vs a <code>BehaviorSubject</code> observable?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>// Signal\nconst count = signal(0); count.set(1); console.log(count());       // 1\n// Observable\nconst count$ = new BehaviorSubject(0); count$.next(1);\ncount$.subscribe(value =&gt; console.log(value));</code></pre></div>","hand":true},{"id":"angular-f0256","card":"q-angular-048-effect","sec":"angular-s048","q":"What does <code>effect()</code> do?","a":"<p>It runs a side effect whenever the signals it reads change.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>effect(() =&gt; {\n  this.analytics.track(&#x27;MESSAGE_COUNT&#x27;, this.count().toString());\n});</code></pre></div>","hand":true},{"id":"angular-f0257","card":"q-angular-048-effect","sec":"angular-s048","q":"How does <code>effect()</code> read signals?","a":"<p>Call the signals inside the callback.</p>","hand":true},{"id":"angular-f0258","card":"q-angular-048-effect","sec":"angular-s048","q":"When does an <code>effect</code> run, and what should it avoid?","a":"<p>It runs at least once, then again when its signals change. It runs asynchronously during change detection. It should not update the UI or do blocking work.</p>","hand":true},{"id":"angular-f0259","card":"q-angular-048-effect","sec":"angular-s048","q":"Where can you create an <code>effect</code>?","a":"<p>It needs an injection context, so create it in the constructor of a component, service or directive.</p>","hand":true},{"id":"angular-f0260","card":"q-angular-048-effect","sec":"angular-s048","q":"What are use cases for <code>effect()</code>?","a":"<p>Analytics, logging, and syncing to storage.</p>","hand":true},{"id":"angular-f0261","card":"q-angular-048-effect","sec":"angular-s048","q":"What do effects look like for logging, local storage and multiple signals?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>effect(() =&gt; { console.log(&#x27;Items changed:&#x27;, this.items().length); });\neffect(() =&gt; { localStorage.setItem(&#x27;preferences&#x27;, JSON.stringify(this.preferences())); });\neffect(() =&gt; { console.log(`User: ${this.username()}, Email: ${this.email()}`); });   // multiple signals</code></pre></div>","hand":true},{"id":"angular-f0262","card":"q-angular-049-async-pipe","sec":"angular-s049","q":"What does the <code>async</code> pipe do and why use it?","a":"<p>It subscribes to a Promise or Observable, triggers change detection, unwraps the value and <strong>unsubscribes automatically</strong>. That avoids leaks and duplicate subscriptions.</p>","hand":true},{"id":"angular-f0263","card":"q-angular-049-async-pipe","sec":"angular-s049","q":"Why prefer <code>async as</code> in a template?","a":"<p>So the pipe is referenced once:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">HTML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>&lt;div *ngIf=&quot;data$ | async as data; else loading&quot;&gt;\n  {{ data.property }}\n&lt;/div&gt;\n&lt;ng-template #loading&gt;Loading...&lt;/ng-template&gt;</code></pre></div>","hand":true},{"id":"angular-f0264","card":"q-angular-049-async-pipe","sec":"angular-s049","q":"How do you use several observables with <code>async</code> in one block?","a":"<p>Combine them in an object with <code>*ngIf</code>:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">HTML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>&lt;div *ngIf=&quot;{ users: users$ | async, posts: posts$ | async } as data&quot;&gt;\n  Users: {{ data.users?.length }}  Posts: {{ data.posts?.length }}\n&lt;/div&gt;</code></pre></div>","hand":true},{"id":"angular-f0265","card":"q-angular-050-rxjs-and-observables","sec":"angular-s050","q":"What is reactive programming and what is an Observable?","a":"<p>Reactive programming handles data that changes over time. An <strong>Observable</strong> is a stream of values over time from the RxJS library. Angular's <code>HttpClient</code> returns them.</p>","hand":true},{"id":"angular-f0266","card":"q-angular-050-rxjs-and-observables","sec":"angular-s050","q":"What does <code>pipe()</code> do in RxJS?","a":"<p>It composes operators where each output feeds the next.</p>","hand":true},{"id":"angular-f0267","card":"q-angular-050-rxjs-and-observables","sec":"angular-s050","q":"How do you chain <code>delay</code> and <code>map</code> operators on an HTTP call?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>this.http.get&lt;Data[]&gt;(&#x27;/api/data&#x27;).pipe(\n  delay(1000),\n  map(data =&gt; data.filter(item =&gt; item.active)),\n  map(data =&gt; data.slice(0, 10))\n);</code></pre></div>","hand":true},{"id":"angular-f0268","card":"q-angular-050-rxjs-and-observables","sec":"angular-s050","q":"What are the common RxJS operators by category?","a":"<ul>\n  <li>Transformation: <code>map</code>, <code>pluck</code>, <code>scan</code></li>\n  <li>Filtering: <code>filter</code>, <code>take</code>, <code>skip</code></li>\n  <li>Combination: <code>merge</code>, <code>concat</code>, <code>combineLatest</code></li>\n  <li>Errors: <code>catchError</code>, <code>retry</code></li>\n  <li>Utility: <code>tap</code> (side effects), <code>delay</code>, <code>timeout</code></li>\n</ul>","hand":true},{"id":"angular-f0269","card":"q-angular-050-rxjs-and-observables","sec":"angular-s050","q":"Observables vs Promises?","a":"<p>Observables: multiple values, lazy (run only when subscribed), cancellable, rich operators. Promises: single value, eager, not cancellable, limited transformation.</p>","hand":true},{"id":"angular-f0270","card":"q-angular-050-rxjs-and-observables","sec":"angular-s050","q":"How do you consume an observable vs a promise?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const data$ = this.http.get(&#x27;/api/data&#x27;);\ndata$.subscribe(value =&gt; console.log(value));\n\nconst data = fetch(&#x27;/api/data&#x27;);\ndata.then(value =&gt; console.log(value));</code></pre></div>","hand":true},{"id":"angular-f0271","card":"q-angular-051-unit-testing-basics","sec":"angular-s051","q":"What is the default Angular testing stack?","a":"<p><strong>Jasmine</strong> (framework) and <strong>Karma</strong> (runner). Specs live in <code>*.spec.ts</code>, created by the CLI.</p>","hand":true},{"id":"angular-f0272","card":"q-angular-051-unit-testing-basics","sec":"angular-s051","q":"How do you run Angular unit tests, and which command is recommended?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>ng test        # CLI\nnpm test       # recommended: uses the locally installed version</code></pre></div>","hand":true},{"id":"angular-f0273","card":"q-angular-051-unit-testing-basics","sec":"angular-s051","q":"What does Karma do when you run tests?","a":"<p>It builds the app, opens a browser, and reruns tests on file save (watch mode). Green is pass; red shows expected vs actual and a stack trace.</p>","hand":true},{"id":"angular-f0274","card":"q-angular-051-unit-testing-basics","sec":"angular-s051","q":"What do you do if Karma shows \"No binary for Chrome browser\"?","a":"<p>Close and reopen the Karma tab.</p>","hand":true},{"id":"angular-f0275","card":"q-angular-051-unit-testing-basics","sec":"angular-s051","q":"What are <code>describe</code>, <code>beforeEach</code> and <code>it</code> in Jasmine?","a":"<ul>\n  <li><code>describe('Name', () =&gt; {...})</code> groups specs into a suite (use the class name).</li>\n  <li><code>beforeEach(() =&gt; {...})</code> runs before every spec for a fresh instance. Declare shared variables with <code>let</code> at suite level and assign them in <code>beforeEach</code>.</li>\n  <li><code>it('should ...', () =&gt; {...})</code> is one spec; start the label with \"should\".</li>\n</ul>","hand":true},{"id":"angular-f0276","card":"q-angular-051-unit-testing-basics","sec":"angular-s051","q":"How do you assert in Jasmine, and what pattern should a test follow?","a":"<p><code>expect(actual).toBe(expected)</code>. Follow Arrange-Act-Assert, with named <code>expected</code> and <code>actual</code> variables.</p>","hand":true},{"id":"angular-f0277","card":"q-angular-052-testing-without-di-pipes-pure-functions","sec":"angular-s052","q":"How do you test a pipe, and is <code>TestBed</code> needed?","a":"<p>Pipes are pure and stateless, so instantiate them directly. No <code>TestBed</code> is needed.</p>","hand":true},{"id":"angular-f0278","card":"q-angular-052-testing-without-di-pipes-pure-functions","sec":"angular-s052","q":"What does a unit test for <code>JoinPipe</code> look like?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>describe(&#x27;JoinPipe&#x27;, () =&gt; {\n  let pipe: JoinPipe;\n\n  beforeEach(() =&gt; {\n    pipe = new JoinPipe();\n  });\n\n  it(&#x27;should join an array using the default separator&#x27;, () =&gt; {\n    const expected = &#x27;1, 2, 3&#x27;;\n    const actual = pipe.transform([1, 2, 3]);\n    expect(actual).toBe(expected);\n  });\n\n  it(&#x27;should join an array using a custom separator&#x27;, () =&gt; {\n    const expected = &#x27;1 | 2 | 3&#x27;;\n    const actual = pipe.transform([1, 2, 3], &#x27; | &#x27;);\n    expect(actual).toBe(expected);\n  });\n});</code></pre></div>","hand":true},{"id":"angular-f0279","card":"q-angular-052-testing-without-di-pipes-pure-functions","sec":"angular-s052","q":"What does the edge-case spec for <code>JoinPipe</code> check?","a":"<p>It follows the same shape as the other specs: <code>pipe.transform([])</code> should be <code>''</code>.</p>","hand":true},{"id":"angular-f0280","card":"q-angular-052-testing-without-di-pipes-pure-functions","sec":"angular-s052","q":"What are the common Jasmine matchers for equality and truthiness?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>expect(value).toBe(expected);           // strict ===\nexpect(value).toEqual(expected);        // deep equality\nexpect(value).not.toBe(expected);\nexpect(value).toBeTruthy();  expect(value).toBeFalsy();\nexpect(value).toBeNull();    expect(value).toBeUndefined();  expect(value).toBeDefined();</code></pre></div>","hand":true},{"id":"angular-f0281","card":"q-angular-052-testing-without-di-pipes-pure-functions","sec":"angular-s052","q":"What are the common Jasmine matchers for numbers, strings and arrays?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>expect(value).toBeGreaterThan(3);  expect(value).toBeLessThan(5);  expect(value).toBeCloseTo(4.2, 1);\nexpect(value).toContain(&#x27;substring&#x27;);   expect(value).toMatch(/pattern/);\nexpect(array).toContain(item);          expect(array).toEqual([1, 2, 3]);</code></pre></div>","hand":true},{"id":"angular-f0282","card":"q-angular-053-testing-with-di-services","sec":"angular-s053","q":"How do you test a service that uses DI?","a":"<p>Configure <code>TestBed</code>, fetch instances with <code>TestBed.inject</code>, replace HTTP with <code>HttpClientTestingModule</code>, and stub the HTTP method with a Jasmine <strong>spy</strong>. Put <code>configureTestingModule</code> in <code>beforeEach</code> so each test gets a clean copy. <code>declarations</code> can be empty or left out.</p>","hand":true},{"id":"angular-f0283","card":"q-angular-053-testing-with-di-services","sec":"angular-s053","q":"What happens in a service test without the HTTP spy, and what does the spy do?","a":"<p>Without the spy, the test times out because the testing module never answers the request. With <code>spyOn(...).and.returnValue(of(data))</code> the call returns immediately with no network.</p>","hand":true},{"id":"angular-f0284","card":"q-angular-053-testing-with-di-services","sec":"angular-s053","q":"Why do observable tests need <code>done</code>?","a":"<p>So Jasmine waits for the subscription.</p>","hand":true},{"id":"angular-f0285","card":"q-angular-053-testing-with-di-services","sec":"angular-s053","q":"How do you set up <code>TestBed</code> and a spy for <code>ApiService</code>?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>beforeEach(() =&gt; {\n  TestBed.configureTestingModule({\n    declarations: [],\n    imports: [HttpClientTestingModule],\n    providers: [ApiService, HttpClient]\n  });\n\n  httpClient = TestBed.inject(HttpClient);\n  service = TestBed.inject(ApiService);\n\n  spyOn(httpClient, &#x27;get&#x27;).and.returnValue(of(EXPECTED_PLAYERS_LIST));\n});</code></pre></div>","hand":true},{"id":"angular-f0286","card":"q-angular-053-testing-with-di-services","sec":"angular-s053","q":"What test data does the <code>ApiService</code> spec use?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const EXPECTED_PLAYERS_LIST: Player[] = [{\n  gems: [&#x27;Diamond&#x27;],\n  id: &#x27;abc123&#x27;,\n  name: &#x27;Abc Xyz&#x27;,\n  online: true,\n  score: 0.12345\n}];</code></pre></div>","hand":true},{"id":"angular-f0287","card":"q-angular-054-testing-with-di-services","sec":"angular-s053","q":"How do you test an observable-returning service method like <code>getAllPlayers$()</code>?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>describe(&#x27;getAllPlayers$()&#x27;, () =&gt; {\n  it(&#x27;should get all players&#x27;, (done: DoneFn) =&gt; {\n    service.getAllPlayers$().subscribe(actual =&gt; {\n      expect(actual).toEqual(EXPECTED_PLAYERS_LIST);\n      done();\n    });\n  });\n});</code></pre></div>","hand":true},{"id":"angular-f0288","card":"q-angular-054-testing-with-di-services","sec":"angular-s053","q":"How do you test finding a player by ID, including a missing ID?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>it(&#x27;should get a player by ID&#x27;, (done: DoneFn) =&gt; {\n  service.getPlayerById$(&#x27;abc123&#x27;).subscribe(actual =&gt; {\n    expect(actual).toEqual(EXPECTED_PLAYERS_LIST.at(0));\n    done();\n  });\n});\n\nit(&#x27;should return undefined if no player is found&#x27;, (done: DoneFn) =&gt; {\n  service.getPlayerById$(&#x27;does-not-exist&#x27;).subscribe(actual =&gt; {\n    expect(actual).toEqual(undefined);\n    done();\n  });\n});</code></pre></div>","hand":true},{"id":"angular-f0289","card":"q-angular-054-testing-with-di-services","sec":"angular-s053","q":"How do you test searching players by name, including no match?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">TypeScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>it(&#x27;should get players by Name&#x27;, (done: DoneFn) =&gt; {\n  service.getPlayersByName$(&#x27;abc&#x27;).subscribe(actual =&gt; {\n    expect(actual).toEqual(EXPECTED_PLAYERS_LIST);\n    done();\n  });\n});\n\nit(&#x27;should return an empty array if no players are found&#x27;, (done: DoneFn) =&gt; {\n  service.getPlayersByName$(&#x27;does-not-exist&#x27;).subscribe(actual =&gt; {\n    expect(actual).toEqual([]);\n    done();\n  });\n});</code></pre></div>","hand":true},{"id":"angular-f0290","card":"q-angular-054-testing-with-di-services","sec":"angular-s053","q":"How should service specs be organized?","a":"<p>Use nested <code>describe</code> blocks to group specs per method. Test success and failure paths.</p>","hand":true},{"id":"angular-f0291","card":"q-angular-055-code-linting-eslint","sec":"angular-s054","q":"What is code linting and what is ESLint?","a":"<p>Static analysis that checks syntax, style and bracket placement without compiling or running, so teams share one style. ESLint is MIT licensed, widely used, and not part of the default install.</p>","hand":true},{"id":"angular-f0292","card":"q-angular-055-code-linting-eslint","sec":"angular-s054","q":"What happens the first time you run <code>ng lint</code>?","a":"<p>The CLI installs and configures ESLint with defaults.</p>","hand":true},{"id":"angular-f0293","card":"q-angular-055-code-linting-eslint","sec":"angular-s054","q":"How do you run lint, and which command is recommended?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>ng lint\nnpm run lint      # recommended</code></pre></div>","hand":true},{"id":"angular-f0294","card":"q-angular-055-code-linting-eslint","sec":"angular-s054","q":"What does the course <code>.eslintrc.json</code> configure?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JSON</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>{\n  &quot;root&quot;: true,\n  &quot;ignorePatterns&quot;: [&quot;projects/**/*&quot;],\n  &quot;overrides&quot;: [\n    {\n      &quot;files&quot;: [&quot;*.ts&quot;],\n      &quot;extends&quot;: [\n        &quot;eslint:recommended&quot;,\n        &quot;plugin:@typescript-eslint/recommended&quot;,\n        &quot;plugin:@angular-eslint/recommended&quot;,\n        &quot;plugin:@angular-eslint/template/process-inline-templates&quot;\n      ],\n      &quot;rules&quot;: {\n        &quot;@typescript-eslint/no-explicit-any&quot;: 0,\n        &quot;@angular-eslint/directive-selector&quot;: [\n          &quot;error&quot;,\n          { &quot;type&quot;: &quot;attribute&quot;, &quot;prefix&quot;: &quot;app&quot;, &quot;style&quot;: &quot;camelCase&quot; }\n        ],\n        &quot;@angular-eslint/component-selector&quot;: [\n          &quot;error&quot;,\n          { &quot;type&quot;: &quot;element&quot;, &quot;prefix&quot;: &quot;app&quot;, &quot;style&quot;: &quot;kebab-case&quot; }\n        ]\n      }\n    },\n    {\n      &quot;files&quot;: [&quot;*.html&quot;],\n      &quot;extends&quot;: [&quot;plugin:@angular-eslint/template/recommended&quot;],\n      &quot;rules&quot;: {}\n    }\n  ]\n}</code></pre></div>","hand":true},{"id":"angular-f0295","card":"q-angular-055-code-linting-eslint","sec":"angular-s054","q":"What does ESLint error output look like?","a":"<p>It includes file, line:column, message and rule:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Text</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>/path/to/file.ts\n  6:12  error  Component selectors should use kebab-case  @angular-eslint/component-selector</code></pre></div>","hand":true},{"id":"angular-f0296","card":"q-angular-055-code-linting-eslint","sec":"angular-s054","q":"Which selector triggers the kebab-case lint error and which passes?","a":"<p><code>selector: 'appRoot'</code> (camelCase) triggers it. <code>selector: 'app-root'</code> passes.</p>","hand":true},{"id":"angular-f0297","card":"q-angular-055-code-linting-eslint","sec":"angular-s054","q":"What is the linting workflow?","a":"<p>Run <code>npm run lint</code>, fix, rerun. Run it before committing and in CI.</p>","hand":true}];
